/* Phase 1 browser-only workflow. Credentials never enter storage or exports. */
const storageKey='utl-etl-demo-v1.2';
const explicitDemoMode=new URLSearchParams(location.search).get('demo')==='1';
const demoProfileIds=new Set(['src-mes','src-qms','target-demo']);
const isStoredDemoConnection=c=>demoProfileIds.has(c?.id)||String(c?.engine||'').includes('(Demo)')||/^(demo-|.*_DEMO$)/i.test(String(c?.host||'')+' '+String(c?.database||''))||['UTL1 MES','UTL2 QMS','Analytics Demo Target'].includes(c?.name);
const seedConnections=()=>explicitDemoMode?[
 {id:'src-mes',name:'UTL1 MES',role:'Source',host:'demo-mes.local',database:'MES_DEMO',auth:'SQL',selected:true,remember:true,revision:1,template:'mes'},
 {id:'src-qms',name:'UTL2 QMS',role:'Source',host:'demo-qms.local',database:'QMS_DEMO',auth:'SQL',selected:true,remember:true,revision:1,template:'qms'},
 {id:'target-demo',name:'Analytics Demo Target',role:'Target',host:'demo-target.local',database:'ANALYTICS_DEMO',auth:'SQL',selected:true,remember:true,revision:1}
]:[];
let rawSaved;try{rawSaved=JSON.parse(localStorage.getItem(storageKey)||'null');}catch{}
// Default app launch removes seeded Demo profiles and cached synthetic runs while preserving real connection profiles.
const safeConnectionProfile=c=>({id:c.id,name:c.name,role:c.role,host:c.host,database:c.database,engine:c.engine,port:c.port,identifier_type:c.identifier_type,protocol:c.protocol,auth:c.auth,selected:!!c.selected,remember:!!c.remember,revision:c.revision,template:c.template,tables:Array.isArray(c.tables)?c.tables:undefined,username:c.rememberUsername?c.username:undefined,rememberUsername:!!c.rememberUsername,timeout:c.timeout,tls:c.tls});
const saved=explicitDemoMode?rawSaved:(rawSaved?{...rawSaved,connections:(Array.isArray(rawSaved.connections)?rawSaved.connections:[]).filter(c=>c&&typeof c==='object'&&!isStoredDemoConnection(c)).map(safeConnectionProfile),scopes:{},analyzed:{},mappings:{},relationships:{}}:null);
if(!explicitDemoMode&&rawSaved){try{localStorage.setItem(storageKey,JSON.stringify(saved));}catch{}}
const demoConnections=saved?.connections?.some(isStoredDemoConnection)?saved.connections:[...seedConnections(),...(saved?.connections||[])];
const P={connections:(explicitDemoMode?demoConnections:(saved?.connections||[])).map(c=>({...c,status:'credentials_required'})),scopes:explicitDemoMode?(saved?.scopes||{}):{},analyzed:explicitDemoMode?(saved?.analyzed||{}):{},mappings:explicitDemoMode?(saved?.mappings||{}):{},relationships:explicitDemoMode?(saved?.relationships||{}):{},role:'Admin',step:0,filter:'',mappingStatus:'all',relationshipView:'graph',pageState:'normal',settingsVersion:saved?.settings?.version||1,limit:saved?.settings?.limit||50,scopeKey:'',timer:null,editing:null,search:'',entity:'all',audit:[]};
const collectionRelationshipStorageKey='utl-etl-collection-relationships-v1';
let collectionRelationships=[];try{const storedRelations=JSON.parse(localStorage.getItem(collectionRelationshipStorageKey)||'[]');if(Array.isArray(storedRelations))collectionRelationships=storedRelations.filter(r=>r&&typeof r.id==='string'&&typeof r.parentKey==='string'&&typeof r.childKey==='string'&&typeof r.parentColumn==='string'&&typeof r.childColumn==='string');}catch{}
const collectionLoadGroupsStorageKey='utl-etl-collection-load-groups-v1';
let collectionLoadGroups=[];try{const storedGroups=JSON.parse(localStorage.getItem(collectionLoadGroupsStorageKey)||'[]');if(Array.isArray(storedGroups))collectionLoadGroups=storedGroups.filter(g=>g&&typeof g.id==='string'&&typeof g.name==='string'&&Array.isArray(g.items));}catch{}
let collectionLoadDraft={id:null,name:'',items:[]};
// Real Source discovery bridge is deliberately transient: never included in Demo persistence.
const liveCanonicalFields=['lot_id','equipment_id','process_code','event_timestamp','job_id'];
let liveSourceDiscovery=null,liveSourceDraft=null;
const realSourceSnapshotStorageKey='utl-etl-real-source-snapshots-v1';
function persistRealSourceSnapshots(){try{localStorage.setItem(realSourceSnapshotStorageKey,JSON.stringify(Object.values(window.realSourceSnapshots||{}).map(({sourceId,sourceName,configRevision,schema,table,object,columns,keys,foreign_keys,discoveredAt,limitations})=>({sourceId,sourceName,configRevision,schema,table,object,columns,keys,foreign_keys,discoveredAt,limitations}))));}catch{ /* Metadata stays available for this session if browser storage is disabled. */ }}
let savedRealSourceSnapshots=[];try{const parsed=JSON.parse(localStorage.getItem(realSourceSnapshotStorageKey)||'[]');if(Array.isArray(parsed))savedRealSourceSnapshots=parsed.filter(s=>s&&typeof s.sourceId==='string'&&typeof s.schema==='string'&&typeof s.table==='string'&&Array.isArray(s.columns));}catch{}
window.realSourceSnapshots=window.realSourceSnapshots||Object.fromEntries(savedRealSourceSnapshots.map(s=>[`${s.sourceId}|${s.schema}|${s.table}`,s]));
window.cacheRealSourceSnapshot=function(snapshot,sourceId=realSourceUI.profileId){const profile=P.connections.find(c=>c.id===sourceId);if(!profile)return;const key=`${profile.id}|${snapshot.schema}|${snapshot.table}`;window.realSourceSnapshots[key]={schema:snapshot.schema,table:snapshot.table,object:snapshot.object,columns:snapshot.columns||[],keys:snapshot.keys||[],foreign_keys:snapshot.foreign_keys||[],discoveredAt:snapshot.discoveredAt||null,limitations:snapshot.limitations||'',sourceId:profile.id,sourceName:profile.name,configRevision:profile.revision||1};persistRealSourceSnapshots();};
window.realSourceSnapshotList=function(){return Object.values(window.realSourceSnapshots);};
window.dropRealSourceSnapshots=function(sourceId){const profile=sourceId&&P.connections.find(c=>c.id===sourceId);for(const [key,snapshot] of Object.entries(window.realSourceSnapshots))if(!sourceId||profile&&snapshot.sourceId===sourceId&&snapshot.configRevision!==(profile.revision||1))delete window.realSourceSnapshots[key];persistRealSourceSnapshots();};
window.sourceHasCurrentSnapshot=function(sourceId){const profile=P.connections.find(c=>c.id===sourceId);return Object.values(window.realSourceSnapshots).some(s=>s.sourceId===sourceId&&s.configRevision===(profile?.revision||1));};
const credentialReady=new Set();
const engineFor=c=>c?.engine||(c?.name==='Data Prep IOT'&&c?.database==='IOT'?'Oracle':'SQL Server (Demo)');
const realConnectorAvailable=c=>isOracleProfile(c); // Other engines are profile-only until an adapter is implemented and verified.
const isOracleProfile=c=>c?.role==='Source'&&engineFor(c)==='Oracle';
const selectedSources=()=>P.connections.filter(c=>c.role==='Source'&&!isOracleProfile(c)&&c.selected&&(!c.tables||c.tables.length));
const targetConnection=()=>P.connections.find(c=>c.role==='Target'&&c.selected);
const canEdit=()=>P.role==='Admin'||P.role==='Data Steward';
const canRun=()=>P.role==='Admin'||P.role==='Operator';
function notify(t){S.notice=t;render();}
function mappingsFor(c){if(!P.mappings[c.id])P.mappings[c.id]=[
 {column:'LOT_NO',field:'lot_id',status:'suggested',required:true,score:'Manual',transform:'keep_string'},
 {column:'MACHINE_CODE',field:'equipment_id',status:'suggested',required:true,score:'94',transform:'trim'},
 {column:'PROCESS',field:'process_code',status:'in_review',required:true,score:'81',transform:'trim'},
 {column:'EVENT_TIME',field:'event_timestamp',status:'suggested',required:true,score:'76',transform:'to_utc'},
 {column:'BATCH_NO',field:'unresolved',status:'in_review',required:false,score:'52',transform:'keep_string',ambiguous:true}
 ];return P.mappings[c.id];}
function relsFor(c){if(!P.relationships[c.id])P.relationships[c.id]=[{id:'lot',left:'dim_lot',right:'fact_process',cardinality:'1:N',status:'suggested'},{id:'equipment',left:'dim_equipment',right:'fact_process',cardinality:'1:N',status:'suggested'},{id:'candidate',left:'fact_process',right:'fact_test (planned)',cardinality:'N:M',status:'suggested',blocked:true}];return P.relationships[c.id];}
function tablesFor(c){return c.id==='src-mes'?['MES.PROCESS_EVENT']:c.id==='src-qms'?['QMS.INSPECTION']:[`DEMO_${c.id.replace(/[^a-z0-9]/gi,'')}.PROCESS_EVENT`];}
function persist(){
 P.scopes[P.scopeKey]={model:JSON.parse(JSON.stringify(sync)),revision:S.revision};
 const connections=P.connections.filter(c=>c.remember).map(c=>({id:c.id,name:c.name,role:c.role,host:c.host,database:c.database,engine:engineFor(c),port:c.port,identifier_type:c.identifier_type,protocol:c.protocol,auth:c.auth,selected:c.selected,remember:true,revision:c.revision,template:c.template,tables:c.tables,username:c.rememberUsername?c.username:undefined,rememberUsername:!!c.rememberUsername,timeout:c.timeout,tls:c.tls}));
 try{localStorage.setItem(storageKey,JSON.stringify({connections,scopes:P.scopes,analyzed:P.analyzed,mappings:P.mappings,relationships:P.relationships,settings:{version:P.settingsVersion,limit:P.limit}}));}catch{ /* UI still works when browser storage is disabled. */ }
}
function bindScope(){
 if(sync.active)return;
 const key=selectedSources().map(c=>c.id+':'+c.revision+':'+(c.tables||tablesFor(c)).join(',')).sort().join('+')+'/'+(targetConnection()?.id||'none')+':'+(targetConnection()?.revision||0);
 if(key===P.scopeKey)return;
 if(P.scopeKey)P.scopes[P.scopeKey]={model:JSON.parse(JSON.stringify(sync)),revision:S.revision};
 const prior=P.scopes[key];const fresh=new DemoSync();
 if(prior){Object.assign(sync,fresh,prior.model);sync.active=null;S.revision=prior.revision||1;}
 else{
  fresh.tables=selectedSources().flatMap(c=>c.tables||tablesFor(c));fresh.selectedTables=[...fresh.tables];fresh.source=[];fresh.seq=0;fresh.tableState={};
  for(const c of selectedSources())for(const table of c.tables||tablesFor(c)){
   fresh.tableState[table]={lastSync:null,lastAttempt:null,watermark:0,initialized:false};
   fresh.add({table,id:'102',lot:c.template==='qms'?'UTL2-000123':'000123',equipment:c.template==='qms'?'EQ-03':'EQ-17',process:'P-ETCH',value:'ok'});
   fresh.add({table,id:'103',lot:'000124',equipment:'EQ-17',process:'P-TEST',value:'ok'});
  }Object.assign(sync,fresh);S.revision=1;
 }
 P.scopeKey=key;sync.scope='demo-job/'+key+'/generation-'+sync.generation;S.mode=sync.initialized?'Incremental':'Initial';invalidate();
}
function updateApproval(){S.approved=selectedSources().length>0&&selectedSources().every(c=>mappingsFor(c).every(m=>['approved','excluded'].includes(m.status))&&relsFor(c).filter(r=>!r.blocked).every(r=>r.status==='approved'));if(S.approved&&S.drift){S.drift=false;if(S.scenario==='drift')S.scenario='none';}}
const baseReason=reason;
reason=function(){if(sync.active)return 'A demo run is already running';if(!canRun())return 'Role cannot start jobs';if(!targetConnection()||!selectedSources().length||!sync.tables.length)return 'Select one Target and at least one Source/table';if(P.connections.filter(c=>c.selected).some(c=>c.status!=='connected'))return 'Connect the selected Source/Target (Demo)';if(selectedSources().some(c=>!P.analyzed[c.id]))return 'Analyze selected Sources';updateApproval();if(S.unsupported&&S.mode==='Incremental')return 'Unsupported incremental: strategy not approved';if(S.drift)return 'Schema drift: review stale mappings';if(S.mode==='Full Refresh'){if(!S.approved)return 'Approve mappings and relationships';if(!S.preview)return 'Generate refresh impact preview';if(!S.prechecked)return 'Run pre-check first';return '';}return baseReason();};
function selectConnection(id,checked){if(sync.active)return notify('Selection locked during Run. Disconnect does not cancel the Run.');const c=P.connections.find(x=>x.id===id);if(c.role==='Target')P.connections.filter(x=>x.role==='Target').forEach(x=>x.selected=x.id===id);else c.selected=checked;bindScope();render();}
function connAction(id,action){const c=P.connections.find(x=>x.id===id);if(P.role!=='Admin')return notify('Admin role required');if(isOracleProfile(c)&&!explicitDemoMode&&location.protocol!=='https:')return notify('Oracle Source credentials and Connect require the local HTTPS application. No credentials were sent.');
 if(!explicitDemoMode&&c?.role==='Source'&&!isOracleProfile(c))return notify(`${engineFor(c)} profile saved; its Connector is not implemented. No connection was attempted.`);
 if(isOracleProfile(c)){
 if(action==='disconnect')return realSourceDisconnectProfile(id);
 if(action==='test'){if(!realSourceUI.session)return openSourceSignIn(id);return openConnection(id);}
  if(action==='connect'){if(!realSourceUI.session)return openSourceSignIn(id);if(realSourceUI.profiles[id]?.tested)return realSourceConnectProfile(id);return openConnection(id);}
 }
 if(action==='disconnect'){c.selected=false;c.status='disconnected';credentialReady.delete(id);bindScope();return notify('Disconnected. Active Run snapshot is unchanged; Cancel Run is separate.');}
 if(!credentialReady.has(id)){c.status='credentials_required';return notify('Credentials required. Enter temporary credentials or use Demo access.');}
 c.status=action==='test'?'testing':'connecting';render();setTimeout(()=>{c.lastTest=new Date().toISOString();c.status=c.error==='auth'?'failed':c.error==='timeout'?'failed':action==='test'?'test_passed':'connected';c.message=c.error==='auth'?'Authentication failed (simulated). Re-enter credentials.':c.error==='timeout'?'Network timeout (simulated). Retry Test.':'';if(c.message)credentialReady.delete(id);render();},350);
}
function demoAccess(id){if(P.role!=='Admin')return;const c=P.connections.find(x=>x.id===id);c.error='';credentialReady.add(id);c.status='connected';c.lastTest=new Date().toISOString();notify('Demo access only. No database session created.');}
function openConnection(id=null){if(P.role!=='Admin')return notify('Admin role required');if(!explicitDemoMode&&location.protocol!=='https:'){S.drawer=false;render();document.querySelector('.content')?.insertAdjacentHTML('afterbegin',`<section class="callout" id="secure-connection-guide"><h3>การเพิ่ม Source ต้องเปิด Local HTTPS ก่อน</h3><p>หน้านี้ใช้ HTTP จึงไม่รับ Username/Password ฐานข้อมูล เพื่อป้องกันข้อมูลลับรั่วไหล</p><ol><li>ดับเบิลคลิกไฟล์ <b>Start U-ETL Test.bat</b> ในโฟลเดอร์โปรเจกต์</li><li>กรอก Local application passphrase ในหน้าต่างที่เปิดขึ้น (ไม่ใช่รหัสผ่าน Oracle)</li><li>เบราว์เซอร์จะเปิด <a href="https://localhost:8443/" target="_blank" rel="noopener">U-ETL ผ่าน Local HTTPS</a> ให้อัตโนมัติ แล้วกด + New connection อีกครั้ง</li></ol><p>การเพิ่มโปรไฟล์และ Test Oracle ทำได้จาก Local HTTPS เท่านั้น</p></section>`);return;}P.editing=id;S.drawer='connection';render();}
function saveConnection(options={}){
 if(P.role!=='Admin')return;if(!explicitDemoMode&&location.protocol!=='https:')return notify('Oracle Source profile changes require local HTTPS.');const form=document.querySelector('#connection-form');if(!form.reportValidity())return;
 const d=new FormData(form);const id=P.editing||'conn-'+Date.now();const old=P.connections.find(x=>x.id===id),wasOracle=isOracleProfile(old),engine=d.get('engine');
 const c={id,name:d.get('name').trim(),role:d.get('role'),host:d.get('host').trim(),database:d.get('database').trim(),engine,port:Number(d.get('port')||1521),identifier_type:d.get('identifier_type')||'Service Name',protocol:d.get('protocol')||'tcps',auth:'SQL',remember:d.get('remember')==='on',rememberUsername:d.get('rememberUsername')==='on',username:d.get('rememberUsername')==='on'?d.get('username'):undefined,timeout:Number(d.get('timeout')),tls:d.get('tls'),revision:(old?.revision||0)+1,selected:old?.selected||false,template:old?.template||'mes',status:'credentials_required'};
 if(engine==='Oracle'&&c.role!=='Source')return notify('Oracle read-only connector is available for Source profiles only.');
 if(!/^[a-zA-Z0-9_.\\,:-]+$/.test(c.host))return notify('Enter a host/instance/port, not a URL or connection string.');
 if(P.connections.some(x=>x.id!==id&&x.name===c.name))return notify('Connection name must be unique');
 if(engineFor(c)!=='Oracle'&&d.get('password')&&d.get('username'))credentialReady.add(id);else credentialReady.delete(id);
 if(old){Object.assign(old,c);delete P.analyzed[id];mappingsFor(old).forEach(m=>m.status='stale');invalidateDatasetRequest('Source connection configuration revision changed',id);window.dropRealSourceSnapshots(id);realSourceForgetCatalogProfile(id);}else P.connections.push(c);
 if(engine==='Oracle'||wasOracle){realSourceUI.tested=false;realSourceUI.metadata=null;realSourceUI.sample=null;realSourceUI.profileId=null;realSourceUI.connection=null;realSourceForgetCatalogProfile(id);liveSourceDiscovery=null;liveSourceDraft=null;}else{invalidate();bindScope();}
 if(options.connectNow){P.editing=id;persist();return id;}const passwordField=document.querySelector('#connection-form input[type=password],#connection-form input[name=password]');if(passwordField)passwordField.value='';S.drawer=false;persist();render();return id;
}
function connectionDrawer(){const c=P.connections.find(x=>x.id===P.editing)||{},oracle=engineFor(c)==='Oracle';return `<h2>${c.id?'Edit':'Add'} connection</h2><form id="connection-form" onsubmit="event.preventDefault();saveConnection()"><div class="form"><label class="field">Connection name<input name="name" required value="${safe(c.name||'')}"></label><label class="field">${oracle?'Host/IP':'Server / Host'}<input name="host" required value="${safe(c.host||'')}"></label><label class="field"><span id="oracle-database-label">${oracle?'Service name/SID':'Database'}</span><input name="database" required value="${safe(c.database||'')}"></label><label class="field">Connection role<select name="role" ${c.id?'disabled':''}><option ${c.role==='Source'?'selected':''}>Source</option><option ${c.role==='Target'?'selected':''}>Target</option></select>${c.id?`<input type="hidden" name="role" value="${c.role}">`:''}</label><label class="field">Connector<select name="engine" onchange="toggleConnectionEngine()"><option value="SQL Server (Demo)" ${!oracle?'selected':''}>SQL Server (Demo)</option><option value="Oracle" ${oracle?'selected':''}>Oracle (Read-only)</option></select></label><label class="field" id="oracle-port-field" ${oracle?'':'hidden'}>Port<input name="port" type="number" min="1" max="65535" value="${safe(c.port||1521)}"></label><label class="field" id="oracle-id-type-field" ${oracle?'':'hidden'}>Connection Identifier Type<select name="identifier_type"><option ${c.identifier_type!=='SID'?'selected':''}>Service Name</option><option ${c.identifier_type==='SID'?'selected':''}>SID</option></select></label><label class="field">Authentication<select name="auth"><option value="SQL" ${!c.auth||c.auth==='SQL'?'selected':''}>Username / Password</option><option disabled>Windows Integrated unavailable</option></select></label><label class="field">Username<input name="username" autocomplete="off" value="${safe(c.username||'')}"></label><label class="field">Password<input name="password" type="password" autocomplete="new-password" ${oracle?'required':''}></label><label class="field" id="oracle-transport-field" ${oracle?'':'hidden'}>Source transport<select name="protocol"><option value="tcps" ${c.protocol!=='tcp'?'selected':''}>TCPS — certificate validation required</option><option value="tcp" ${c.protocol==='tcp'?'selected':''}>TCP — approved VPN/network only</option></select></label><label class="field">Timeout (seconds)<input name="timeout" type="number" min="1" max="30" value="${c.timeout||15}"></label></div><div id="oracle-acknowledgements" ${oracle?'':'hidden'}><p><label><input name="readonly_ack" type="checkbox" required> ยืนยันบัญชี/ขอบเขตที่ได้รับอนุญาตให้อ่านอย่างเดียว</label></p><p><label><input name="tcp_ack" type="checkbox"> กรณี TCP: IT/DBA อนุมัติเครือข่าย/VPN แล้ว</label></p></div><p id="oracle-drawer-note" class="muted" ${oracle?'':'hidden'}>Read-only Source connection. Password is sent only over HTTPS and is never saved. Local application sign-in is required before Test.</p><div class="actions"><button type="button" onclick="const i=document.querySelector('#connection-form [name=password]');i.type=i.type==='password'?'text':'password';setTimeout(()=>i.type='password',5000)">Show/Hide temporarily</button>${oracle?`<button type="button" class="primary" onclick="realSourceTestProfile('${c.id||''}')">Test Connection (read-only)</button>`:''}<button class="primary" type="submit">Save connection</button></div><div class="actions"><label><input name="remember" type="checkbox" ${c.remember?'checked':''}> Remember connection</label><label><input name="rememberUsername" type="checkbox" ${c.rememberUsername?'checked':''}> Remember username</label><label><input type="checkbox" disabled> Save password securely (unavailable)</label></div><p class="muted">Password is discarded after validation and never stored in browser storage. Source remains read-only; no ETL or Target publish.</p></form>`;}
function toggleConnectionEngine(){const oracle=document.querySelector('#connection-form [name=engine]').value==='Oracle';for(const id of ['oracle-port-field','oracle-id-type-field','oracle-transport-field','oracle-drawer-note','oracle-acknowledgements'])document.getElementById(id).hidden=!oracle;document.querySelector('#connection-form [name=password]').required=oracle;document.querySelector('#connection-form [name=readonly_ack]').required=oracle;document.getElementById('oracle-database-label').textContent=oracle?'Service name/SID':'Database';}
sources=function(){const card=(c,role)=>{const oracle=isOracleProfile(c),status=oracle?(realSourceUI.tested&&realSourceUI.profileId===c.id?'<span class="badge ok">Oracle test passed · read-only</span>':c.status==='failed'?'<span class="badge err">Test failed</span>':'<span class="badge warn">Oracle · test required</span>'):st(c.status);return `<div class="card" data-source-profile="${safe(c.id)}"><label>${oracle?'<input type="checkbox" disabled title="Oracle profile is excluded from synthetic Demo ETL">':'<input type="'+(role==='Source'?'checkbox':'radio')+'" name="target" '+(c.selected?'checked':'')+' onchange="selectConnection(\''+c.id+'\',this.checked)">'} <b>${safe(c.name)}</b></label> ${status}<p>${safe(c.host)} / ${safe(c.database)}</p><small>${oracle?'Oracle read-only profile · ':'Demo connector · '}Last tested: ${when(c.lastTest)} · revision ${c.revision}</small>${c.message?`<p class="error">${safe(c.message)}</p>`:''}<div class="actions"><button onclick="connAction('${c.id}','test')">Test Connection</button><button onclick="connAction('${c.id}','connect')">Connect</button>${oracle?'':`<button onclick="demoAccess('${c.id}')">Use Demo access</button>`}<button onclick="openConnection('${c.id}')">Edit</button><button onclick="connAction('${c.id}','disconnect')">Disconnect</button></div>${oracle?'':`<label class="field">Simulate error<select aria-label="Error ${c.id}" onchange="P.connections.find(c=>c.id==='${c.id}').error=this.value"><option value="">None</option><option value="auth">Authentication failed</option><option value="timeout">Network timeout</option></select></label>${role==='Source'?`<label><input type="checkbox" ${c.tables?.length===0?'':'checked'} onchange="P.connections.find(c=>c.id==='${c.id}').tables=this.checked?tablesFor(P.connections.find(c=>c.id==='${c.id}')):[];bindScope();render()"> ${tablesFor(c)[0]}</label>`:''}`}</div>`;};return intro('Connection Setup','Choose Source connections and one Target. Oracle read-only operates inside the existing profile card; Demo ETL stays synthetic.',`<button class="primary" onclick="openConnection()" ${P.role!=='Admin'?'disabled':''}>＋ Add connection</button>`)+['Source','Target'].map(role=>`<div class="title">${role==='Source'?'Source Databases (multiple allowed)':'Target Analytics Database (one per Run)'}</div><div class="grid c2">${P.connections.filter(c=>c.role===role).map(c=>card(c,role)).join('')}</div>`).join('')+`<div class="title">Discover / Profile · Demo</div><div class="card"><button class="primary" onclick="analyzeSources()">Analyze selected Demo tables</button><button onclick="go('mapping')">Continue to Data Mapping →</button>${selectedSources().map(c=>P.analyzed[c.id]?`<p>${safe(c.name)}: ${P.analyzed[c.id].count} synthetic samples · ${when(P.analyzed[c.id].at)} · Grain: one row per source process event · PK event_id · null lot_id 0%</p>`:'').join('')}</div>`;};
function analyzeSources(){if(!canEdit())return notify('Admin or Data Steward required');if(P.connections.filter(c=>c.selected).some(c=>c.status!=='connected')||!selectedSources().length||!targetConnection())return notify('Connect selected Sources and Target first');if(!sync.tables.length)return notify('Select at least one table');P.loading=true;render();setTimeout(()=>{for(const c of selectedSources()){P.analyzed[c.id]={count:sync.source.filter(r=>(c.tables||tablesFor(c)).includes(r.table)).length,at:new Date().toISOString()};mappingsFor(c);relsFor(c);}P.loading=false;invalidate();S.page='mapping';render();},500);}
function launchLiveSourceDiscovery(){if(!canEdit())return notify('Admin or Data Steward role required to review Source metadata');S.page='sources';S.notice='Use the Oracle Test Connection action inside the existing Data Prep IOT profile card.';render();}
function liveCandidate(column){return ({LOT_NO:'lot_id',MACHINE_CODE:'equipment_id',EQUIPMENT_ID:'equipment_id',PROCESS:'process_code',PROCESS_CODE:'process_code',EVENT_TIME:'event_timestamp',EVENT_TIMESTAMP:'event_timestamp',JOB_ID:'job_id'})[column]||'';}
function updateLiveMappingSummary(){if(!liveSourceDraft)return;const rows=Object.values(liveSourceDraft.rows),reviewed=rows.filter(r=>r.status==='reviewed_draft').length,suggested=rows.filter(r=>r.field).length;const node=document.querySelector('#live-mapping-summary');if(node)node.textContent=`${rows.length} live metadata columns · ${suggested} name-based suggestions/selections · ${reviewed} reviewed as draft · Target entity ${liveSourceDraft.target||'not selected'} · session only`}
function setLiveMappingTarget(value){if(!liveSourceDraft)return;liveSourceDraft.target=value;updateLiveMappingSummary();}
function setLiveMappingField(column,value){if(!liveSourceDraft?.rows[column])return;const row=liveSourceDraft.rows[column];row.field=value;row.status='in_review';const state=document.querySelector(`[data-live-status="${CSS.escape(column)}"]`);if(state)state.textContent=value?'Suggestion · needs review':'Unmapped · needs review';updateLiveMappingSummary();}
function setLiveMappingReason(column,value){if(liveSourceDraft?.rows[column])liveSourceDraft.rows[column].reason=value;}
function recordLiveMappingDraft(column){if(!canEdit())return notify('Admin or Data Steward role required');const row=liveSourceDraft?.rows[column];if(!row)return;if(!row.field&&!row.reason.trim())return notify('Choose a canonical field or enter a reason before recording this draft review.');row.status='reviewed_draft';const state=document.querySelector(`[data-live-status="${CSS.escape(column)}"]`);if(state)state.textContent='Reviewed in this session (draft)';updateLiveMappingSummary();notify('Draft review recorded in this session only; not approved for ETL.');}
function liveDiscoveryPanel(){
 const start='<div id="live-source-mapping" class="card"><div class="callout"><b>REAL SOURCE · metadata only</b> — Connection and Discovery are available inside the existing Data Sources menu. This section is kept separate from synthetic Demo mappings; no sample rows or credentials are used as mapping evidence.</div><button class="primary" onclick="launchLiveSourceDiscovery()">Open Data Sources to Discover</button>';
 if(!liveSourceDiscovery||!liveSourceDraft)return start+'<p class="muted">In Data Sources, sign in to the local read-only service, Test Connection, then Discover an authorized table. Return here to review metadata. Draft review does not enable ETL.</p></div>';
 const primary=liveSourceDiscovery.keys.filter(k=>k[1]==='P').map(k=>k[2]),entities=['dim_lot','lot_identity_crosswalk','dim_equipment','dim_process','fact_process'];
 const rows=liveSourceDiscovery.columns.map(c=>{const [name,ordinal,type,nullable]=c,row=liveSourceDraft.rows[name],evidence=primary.includes(name)?'Primary key':liveSourceDiscovery.foreign_keys.some(f=>f[1]===name)?'Foreign key':'Name/type only';return `<tr><td>${safe(name)}</td><td>${safe(type)} / ${nullable==='N'?'Not nullable':'Nullable'}</td><td>${safe(evidence)}</td><td><select aria-label="Live canonical field ${safe(name)}" onchange="setLiveMappingField('${safe(name)}',this.value)"><option value="">Unmapped</option>${liveCanonicalFields.map(f=>`<option value="${f}" ${row.field===f?'selected':''}>${f}</option>`).join('')}</select></td><td><input aria-label="Live review note ${safe(name)}" value="${safe(row.reason)}" placeholder="Reason if unmapped" oninput="setLiveMappingReason('${safe(name)}',this.value)"></td><td><span data-live-status="${safe(name)}">${row.status==='reviewed_draft'?'Reviewed in this session (draft)':row.field?'Suggestion · needs review':'Unmapped · needs review'}</span></td><td><button onclick="recordLiveMappingDraft('${safe(name)}')">Record draft review</button></td></tr>`;}).join('');
 return start+`<h3>REAL SOURCE · ${safe(liveSourceDiscovery.schema)}.${safe(liveSourceDiscovery.table)}</h3><p>Discovery time: ${safe(liveSourceDiscovery.discoveredAt)} · PK column(s): ${safe(primary.join(', ')||'None reported')} · Business grain remains unconfirmed.</p><p id="live-mapping-summary" role="status"></p><label class="field">Candidate Target entity (not approved)<select onchange="setLiveMappingTarget(this.value)"><option value="">Not selected</option>${entities.map(e=>`<option ${liveSourceDraft.target===e?'selected':''}>${e}</option>`).join('')}</select></label><div class="card tablewrap"><table class="table"><thead><tr><th>Source column</th><th>Type / nullable</th><th>Metadata evidence</th><th>Canonical field</th><th>Review note</th><th>Draft state</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><p class="muted">Suggestions are name/type hints, not AI, confirmed business meaning or approval. Only existing Prototype dictionary fields are selectable; new fields need a separate dictionary decision. No mapping bundle is saved and no ETL can start from this panel.</p></div>`;
}
mapping=function(){const cs=selectedSources();return intro('Data Mapping','Review live Oracle metadata here alongside clearly separated synthetic Demo mappings; suggestions are not approval')+liveDiscoveryPanel()+`<div class="callout">DEMO MAPPINGS BELOW · synthetic fixtures only · separate from the live metadata review above</div><div class="toolbar"><label>Search <input aria-label="Mapping search" value="${safe(P.search)}" onchange="P.search=this.value;render()"></label><label>Status <select onchange="P.mappingStatus=this.value;render()"><option value="all">All</option>${['suggested','in_review','approved','excluded','stale','rejected'].map(s=>`<option ${P.mappingStatus===s?'selected':''}>${s}</option>`).join('')}</select></label></div>${cs.map(c=>`<h3>${safe(c.name)} ${!P.analyzed[c.id]?'(Analyze required)':''}</h3><div class="card tablewrap"><table class="table"><tr><th>Source column</th><th>Canonical field</th><th>Score</th><th>Status</th><th></th></tr>${mappingsFor(c).filter(m=>(P.mappingStatus==='all'||m.status===P.mappingStatus)&&(m.column+m.field).toLowerCase().includes(P.search.toLowerCase())).map(m=>`<tr><td>${m.column}</td><td>${m.field}</td><td>${m.score}</td><td>${st(m.status)}</td><td><button onclick="S.drawer='field:${c.id}:${m.column}';render()">Review</button></td></tr>`).join('')}</table><button onclick="bulkReview('${c.id}')">Review bulk approval impact</button></div>`).join('')}${cs.length?'':'<p>Select a Source first</p>'}`;};
function reviewField(id,column,action){if(!canEdit())return notify('Role cannot edit mappings');const m=mappingsFor(P.connections.find(c=>c.id===id)).find(x=>x.column===column);if(action==='excluded'&&m.required)return notify('Required key cannot be excluded');if(action==='excluded'&&!document.querySelector('#review-reason').value.trim())return notify('Exclusion requires a reason');if(action==='approved'&&m.ambiguous&&document.querySelector('#standard-field').value==='unresolved')return notify('Resolve BATCH_NO meaning explicitly before approval');m.field=document.querySelector('#standard-field')?.value||m.field;m.status=action;m.reason=document.querySelector('#review-reason').value.trim();m.reviewedBy=P.role;m.reviewedAt=new Date().toISOString();S.revision++;invalidate();updateApproval();S.drawer=false;P.audit.push({action,column,revision:S.revision,at:new Date().toISOString()});render();}
function bulkReview(id){S.drawer='bulk:'+id;render();}
function bulkApprove(id){if(!canEdit())return;const c=P.connections.find(c=>c.id===id);if(!P.analyzed[id])return notify('Analyze first');mappingsFor(c).filter(m=>!m.ambiguous).forEach(m=>m.status='approved');S.revision++;invalidate();S.drawer=false;updateApproval();render();}
function fieldDrawer(id,column){const m=mappingsFor(P.connections.find(c=>c.id===id)).find(m=>m.column===column);return `<h2>Review ${column}</h2><p>Source ID: ${id} · Grain: source process event · Key: event_id</p><p>Evidence: synthetic sample, n=${P.analyzed[id]?.count||0}. Type varchar. ${m.ambiguous?'BATCH_NO could mean lot_id or job_id; evidence is insufficient.':'Column name and fixture pattern support this candidate.'}</p><p>Original sample: ${column==='LOT_NO'?'000123':column==='BATCH_NO'?'B-000123':'P-ETCH'} · Alternatives: ${m.ambiguous?'lot_id / job_id / exclude':'manual dictionary override'}</p><label class="field">Standard field<select id="standard-field">${['unresolved','lot_id','equipment_id','process_code','event_timestamp','job_id'].map(f=>`<option ${f===m.field?'selected':''}>${f}</option>`).join('')}</select></label><label class="field">Reason<textarea id="review-reason"></textarea></label><p>Transform: ${m.transform} · required: ${m.required} · revision ${S.revision}</p><div class="actions">${['approved','rejected','excluded'].map(a=>`<button onclick="reviewField('${id}','${column}','${a}')">${a==='approved'?'Approve / Override':a==='rejected'?'Reject':'Exclude'}</button>`).join('')}</div>`;}
relationships=function(){return intro('Relationships','Review cardinality and evidence before publishing')+`<div class="toolbar"><button onclick="P.relationshipView='graph';render()">Graph view</button><button onclick="P.relationshipView='list';render()">List view</button></div>${selectedSources().map(c=>`<h3>${safe(c.name)}</h3><div class="card">${P.relationshipView==='graph'?`<div class="relationship-graph">${relsFor(c).map(r=>`<div class="relationship-edge ${r.status==='approved'?'approved-edge':'suggested-edge'}"><span>${r.left}</span><span> ${r.status==='approved'?'━━━━':'┄┄┄┄'} ${r.cardinality} </span><span>${r.right}</span><button onclick="S.drawer='rel:${c.id}:${r.id}';render()">Evidence</button></div>`).join('')}</div>`:`<table class="table"><tr><th>Relationship</th><th>Cardinality</th><th>Status</th><th></th></tr>${relsFor(c).map(r=>`<tr><td>${r.left} → ${r.right}</td><td>${r.cardinality}</td><td>${st(r.status)}</td><td><button onclick="S.drawer='rel:${c.id}:${r.id}';render()">Evidence</button></td></tr>`).join('')}</table>`}</div>`).join('')}`;};
function approveRelationship(id,key){if(!canEdit())return;const r=relsFor(P.connections.find(c=>c.id===id)).find(r=>r.id===key);if(r.blocked)return notify('N:M candidate cannot join facts. Keep excluded from load scope.');r.status='approved';S.revision++;invalidate();updateApproval();S.drawer=false;render();}
const priorDrawer=drawer;
drawer=function(){let body;if(S.drawer==='connection')body=connectionDrawer();else if(String(S.drawer).startsWith('field:')){const [,id,col]=S.drawer.split(':');body=fieldDrawer(id,col);}else if(String(S.drawer).startsWith('bulk:')){const id=S.drawer.slice(5);body=`<h2>Bulk approval impact</h2><p>Approve LOT_NO, MACHINE_CODE, PROCESS, EVENT_TIME. BATCH_NO remains ambiguous and is excluded from bulk approval. Preview/pre-check will expire.</p><button onclick="bulkApprove('${id}')">Confirm safe bulk approval</button>`;}else if(String(S.drawer).startsWith('rel:')){const [,id,key]=S.drawer.split(':');const r=relsFor(P.connections.find(c=>c.id===id)).find(r=>r.id===key);body=`<h2>Relationship evidence</h2><p>${r.left} → ${r.right}, cardinality ${r.cardinality}</p><p>Fixture sample overlap only. Composite Source/site key; do not join facts directly.${r.blocked?' Many-to-many remains out of scope.':''}</p><button onclick="approveRelationship('${id}','${key}')" ${r.blocked?'disabled':''}>Approve relationship</button>`;}else if(String(S.drawer).startsWith('row:')){const row=sync.target[Number(S.drawer.slice(4))];body=`<h2>Lot detail / Lineage</h2><p>Lot ${row.lot} · event ${row.id}</p><p>Source ${row.table}#${row.id}</p><p>Target event key: ${row.table}/${row.id}</p><p>Run scope ${safe(sync.scope)}. Mapping bundle references are immutable in History.</p>`;}else return priorDrawer();return `<div class="overlay" onclick="S.drawer=false;render()"></div><aside class="drawer"><button class="close" onclick="S.drawer=false;render()">×</button>${body}</aside>`;};
previewSync=function(){updateApproval();if(!S.approved||S.drift)return notify('Approve selected mappings and relationships');S.preview=true;S.prechecked=false;render();};
const priorEtl=etl;
etl=function(){let html=priorEtl().replace('Reload resets Demo state.','Reload retains synthetic records; interrupted browser Runs require Retry.').replace('Full Refresh execution is unavailable in this milestone.','Demo will replace selected tables only after successful Publish.');html=html.replace('</select></label></div><div class="actions">',`<option value="partial" ${S.scenario==='partial'?'selected':''}>Partial failure: second table fails</option><option value="warning" ${S.scenario==='warning'?'selected':''}>Quality warning / quarantine</option></select></label></div><div class="actions">`);if(S.preview)html+=`<div class="title">Before / After preview</div><div class="card tablewrap"><table class="table"><tr><th>Source LOT_NO</th><th>Target lot_id</th><th>Validation</th></tr>${sync.source.map(r=>`<tr><td>${safe(r.lot)}</td><td>${safe(r.lot)}</td><td>${r.lot?'Pass':'Quarantine: required lot_id'}</td></tr>`).join('')}</table>${S.mode==='Full Refresh'?`<p>Impact: replace ${sync.target.length} selected Target records; create generation ${sync.generation+1} after successful Publish. No database drop.</p><label><input id="confirm-refresh" type="checkbox"> Confirm selected-table replacement (Demo)</label>`:''}</div>`;if(sync.active)html+=`<div class="card"><p>Connecting → Extracting → Staging → Transforming → Integrating → Validating → Publishing</p><button onclick="cancelRun()">Cancel Run</button><p>Stop at the simulated pre-publish batch boundary. Disconnect is separate.</p></div>`;const published=sync.history.find(r=>['succeeded','succeeded_with_warnings'].includes(r.state));if(published&&published.bundle!=='DEMO-BUNDLE-'+S.revision)html+=`<div class="callout">Mapping revision changed since ${safe(published.bundle)}. Review historical data impact: Incremental does not backfill older data under new mapping rules. Backfill is a separate bounded Backend job (Planned). Demo transforms do not execute arbitrary mapping rules.</div>`;return html;};
startSync=function(retryOf=null){if(!canRun())return notify('Role cannot start jobs');const ready=reason();if(!retryOf&&ready)return notify(ready);if(retryOf){const original=sync.history.find(r=>r.id===retryOf);if(S.drift||S.scenario==='drift')return notify('Schema drift: review stale mappings before Retry');if(S.unsupported&&original?.mode==='Incremental')return notify('Unsupported incremental: strategy not approved; Retry blocked');if(sync.active||P.connections.filter(c=>c.selected).some(c=>c.status!=='connected')||!S.approved)return notify('Reconnect and approve current scope before Retry');}if(S.mode==='Full Refresh'&&!retryOf&&!document.querySelector('#confirm-refresh')?.checked)return notify('Confirm Full Refresh impact first');try{const r=sync.begin(S.mode,S.scenario,S.revision,retryOf);const original=retryOf&&sync.history.find(x=>x.id===retryOf);r.connectionSnapshot=original?.connectionSnapshot||P.connections.filter(c=>c.selected).map(c=>({id:c.id,revision:c.revision}));r.settingsVersion=original?.settingsVersion||P.settingsVersion;S.run=r.state;persist();render();P.timer=setTimeout(()=>{if(!sync.active)return;sync.finish();S.mode=sync.initialized?'Incremental':'Initial';S.scenario='none';invalidate();persist();bindScope();render();},2200);}catch(e){notify(e.message);}};
function cancelRun(){clearTimeout(P.timer);sync.cancel();invalidate();persist();render();}
const priorOption=option;
option=function(field,value){if(field==='scenario'&&value==='drift')selectedSources().forEach(c=>mappingsFor(c).forEach(m=>{if(m.required)m.status='stale';}));priorOption(field,value);if(field==='scenario'&&value==='drift'){updateApproval();render();}};
const priorQuality=quality;
const overviewBeforeCompletion=overview;
overview=function(){return overviewBeforeCompletion()+`<div class="title">Scope readiness</div><div class="card"><p>Selected Sources: ${selectedSources().map(c=>safe(c.name)+' '+st(c.status)).join(' / ')||'None'}<br>Target: ${safe(targetConnection()?.name||'None')} (${st(targetConnection()?.status||'Not selected')})</p><p>Mapping pending: ${selectedSources().flatMap(c=>mappingsFor(c)).filter(m=>!['approved','excluded'].includes(m.status)).length}</p><p>${safe(reason()||'Ready for Demo load')}</p></div>`;};
quality=function(){const r=latest();return intro('Data Quality','Shared Run outcomes, sanitized rejected records')+(r?`<h3>${r.id} ${st(r.state)}</h3>${counts(r.counts)}<div class="card"><p>Published in this Run: ${r.counts.inserted+r.counts.updated+r.counts.unchanged}</p><p>Target rows now: ${sync.target.length}</p><p>Extracted = published + quarantined + filtered + duplicate/superseded + pending. Publish is per Table; failed or cancelled rows remain pending.</p></div>`:'<div class="card">No demo Run yet.</div>')+`<div class="title">Quality rules and quarantine</div><div class="card"><p>Blocker: required event key · Warning: missing lot_id → quarantine · Info: unchanged events</p><table class="table"><tr><th>Event</th><th>Rule</th><th>Original Run</th><th>Status</th></tr>${sync.quarantine.map(q=>`<tr><td>${q.table}#${q.id}</td><td>${q.rule}</td><td>${q.runId}</td><td>${q.status}</td></tr>`).join('')}</table>${sync.quarantine.length?'<button onclick="reprocessQuarantine()">Reprocess corrected demo rows</button>':'<p>No quarantined rows</p>'}</div>`;};
function reprocessQuarantine(){if(!canRun()||sync.active)return;for(const q of sync.quarantine){const r=sync.source.find(x=>x.table===q.table&&x.id===q.id);if(r){r.lot='000129';r.seq=++sync.seq;q.status='corrected; awaiting next Publish';}}invalidate();notify('Synthetic rows corrected. Generate preview/pre-check and run Incremental to Publish.');}
const priorRuns=runs;
runs=function(){return priorRuns().replace('Session-only Demo records.','Locally saved synthetic Demo records.')+`<div class="title">Run details</div>${sync.history.map(r=>`<details class="card"><summary>${r.id}: ${r.result||r.state}</summary><p>Bundle ${r.bundle} · Scope ${safe(r.scope)} · Retry of ${r.retryOf||'—'} · Duration ${r.endedAt?((new Date(r.endedAt)-new Date(r.startedAt))/1000).toFixed(1)+'s':'Running'}</p><p>Connection config snapshot: ${safe(JSON.stringify(r.connectionSnapshot||[]))}</p><table class="table"><tr><th>Table</th><th>Status</th><th>Insert</th><th>Update</th><th>Unchanged</th><th>Pending</th></tr>${r.tables.map(t=>`<tr><td>${t.table}</td><td>${st(t.state)}</td><td>${t.counts.inserted}</td><td>${t.counts.updated}</td><td>${t.counts.unchanged}</td><td>${t.counts.pending}</td></tr>`).join('')}</table>${r.state==='failed'?`<button onclick="startSync('${r.id}')">Retry failed tables</button>`:''}</details>`).join('')}`;};
explorer=function(){const rows=sync.target.filter(r=>(P.entity==='all'||r.table===P.entity)&&r.lot.toLowerCase().includes(P.filter.toLowerCase())).slice(0,P.limit);return intro('Data Explorer','Published synthetic events only')+`<div class="toolbar"><label>Target table <select onchange="P.entity=this.value;render()"><option value="all">All tables</option>${sync.tables.map(t=>`<option ${P.entity===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Lot filter <input aria-label="Lot filter" value="${safe(P.filter)}" onchange="P.filter=this.value;render()"></label><label>Row limit <input type="number" min="1" max="50" value="${P.limit}" onchange="P.limit=Math.min(50,Math.max(1,Number(this.value)));render()"></label></div><div class="card tablewrap"><table class="table"><tr><th>event_id</th><th>lot_id</th><th>equipment_id</th><th>process</th><th>Lineage</th></tr>${rows.map(r=>`<tr><td>${r.id}</td><td>${r.lot}</td><td>${r.equipment}</td><td>${r.process}</td><td><button onclick="S.drawer='row:${sync.target.indexOf(r)}';render()">${r.table}#${r.id}</button></td></tr>`).join('')}</table>${rows.length?'':'<p>Empty: no published rows match this scope/filter.</p>'}</div>`;};
settings=function(){return intro('Settings','Versioned demo policy; AI adapter disabled')+`<div class="grid c2"><div class="card"><h3>Canonical dictionary</h3><p>lot_id: string preserving leading zeros<br>equipment_id: site-scoped equipment<br>process_code: definition/version<br>event_timestamp: UTC after confirmed Source timezone</p></div><div class="card"><h3>Policy version ${P.settingsVersion}</h3><p>AI: disabled · Samples outbound: disabled</p><p>Retention: Demo browser storage until reset</p><button onclick="if(P.role==='Admin'){P.settingsVersion++;notify('New settings version recorded for next Run')}else notify('Admin required')">Save new policy revision</button></div><div class="card"><h3>Users / roles (UI simulation)</h3><select aria-label="Demo role" onchange="P.role=this.value;render()">${['Admin','Data Steward','Operator','Viewer'].map(r=>`<option ${P.role===r?'selected':''}>${r}</option>`).join('')}</select><p>No real authentication/authorization. Backend contract requires server-side enforcement.</p></div><div class="card"><h3>Runtime</h3><p>Secret store unavailable · Windows identity unavailable</p><p>Scheduler / CDC planned</p><button onclick="P.connections.forEach(c=>c.status='credentials_required');credentialReady.clear();invalidate();notify('Simulated restart: credentials required; Run records retained')">Simulate credential restart</button></div></div>`;};
const priorSummary=summary;
summary=function(){return priorSummary().replace('Analytics Demo Target',safe(targetConnection()?.name||'Not selected')).replace('Browser-memory Demo only.',explicitDemoMode?'Synthetic Demo records saved locally. Browser is not a background Worker.':'No Demo rows loaded. Real Target/ETL is not configured.');};
// Dataset-first intake and metadata-only candidate review, hosted in the existing Overview/Mapping pages.
let activeDatasetRequest=null,activeDatasetReviews=[],activeDatasetDecisions={},activeDatasetDefinition=null,datasetReviewDrafts={},datasetSourceMode=explicitDemoMode?'demo':'real';
let datasetFormDraft={name:'',purpose:'',businessFields:'',sourceMode:'demo',sourceIds:[],from:'',to:'',filterRequest:'',grain:'unknown',grainRationale:'',targetId:''};
const datasetDemoColumns=[['LOT_NO',1,'VARCHAR','N'],['INPUT_QTY',2,'NUMBER','Y'],['OUTPUT_QTY',3,'NUMBER','Y'],['PACKAGE_CODE',4,'VARCHAR','Y'],['CUSTOMER_CODE',5,'VARCHAR','Y'],['PRODUCT_CODE',6,'VARCHAR','Y'],['PROD_CODE',7,'VARCHAR','Y'],['PROD_AREA',8,'VARCHAR','Y'],['MACHINE_CODE',9,'VARCHAR','Y'],['PROCESS',10,'VARCHAR','Y'],['EVENT_TIME',11,'TIMESTAMP','Y'],['BATCH_NO',12,'VARCHAR','Y']];
function captureDatasetDraft(form){if(!form)return;const data=new FormData(form);datasetFormDraft={...datasetFormDraft,name:String(data.get('datasetName')||''),purpose:String(data.get('purpose')||''),businessFields:String(data.get('businessFields')||''),sourceMode:String(data.get('sourceMode')||'demo'),sourceIds:[...form.querySelectorAll('[name=sourceIds]:checked')].map(x=>x.value),from:String(data.get('from')||''),to:String(data.get('to')||''),filterRequest:String(data.get('filterRequest')||''),grain:String(data.get('grain')||'unknown'),grainRationale:String(data.get('grainRationale')||''),targetId:String(data.get('targetId')||'')};}
function setDatasetSourceMode(value,form){captureDatasetDraft(form);datasetSourceMode=value;datasetFormDraft.sourceMode=value;datasetFormDraft.sourceIds=[];render();}
function datasetRequestPanel(){
 const mode=datasetSourceMode||datasetFormDraft.sourceMode||(explicitDemoMode?'demo':'real');
 const sourceChoices=mode==='real'?window.realSourceSnapshotList():(window.datasetWorkflowDemoSources||[]);
 const realReady=sourceChoices.length>0;
 const selectedSources=datasetFormDraft.sourceIds?.length?datasetFormDraft.sourceIds:mode==='real'?sourceChoices.map(s=>`${s.sourceId}|${s.schema}|${s.table}`):sourceChoices.slice(0,1).map(c=>c.id);
 const targetOptions=P.connections.filter(c=>c.role==='Target');
 return `<div class="workflow-heading"><div><span class="eyebrow">STEP 1 · DESCRIBE YOUR DATASET</span><h2>What do you want to analyze?</h2><p>บอกวัตถุประสงค์และฟิลด์ด้วยภาษาธุรกิจ แล้วระบบจะแสดงแผนให้ตรวจ</p></div><span class="badge warn">Prototype · no AI</span></div><section class="card" id="dataset-request-card"><div class="callout"><b>${mode==='demo'?'DEMO · Synthetic sources only':'REAL SOURCE · Metadata only'}</b> — คำแนะนำในรอบนี้ยังเป็นกฎตัวอย่าง ไม่ใช่ AI และไม่อ่านข้อมูลจริงในขั้นนี้</div>${activeDatasetRequest?`<div class="actions"><button type="button" onclick="editDatasetRequest()">Edit request (review will reset)</button><span>${activeDatasetDefinition?'Definition approved in this browser session only':'Review not yet approved'}</span></div>`:''}<form id="dataset-request-form" oninput="captureDatasetDraft(this)" onsubmit="submitDatasetRequest(event)">
 <div class="form"><label class="field">Dataset name<input name="datasetName" required maxlength="120" value="${safe(datasetFormDraft.name)}" placeholder="Yield Analysis"></label><label class="field">Business purpose<textarea name="purpose" required maxlength="2000" placeholder="What decision or analysis should this dataset support?">${safe(datasetFormDraft.purpose)}</textarea></label></div>
 <label class="field">Business fields you need · one per line<textarea name="businessFields" required rows="5" placeholder="Lot number&#10;Input quantity&#10;Output quantity&#10;Package code&#10;Customer code&#10;Product code&#10;Production code&#10;Production area">${safe(datasetFormDraft.businessFields)}</textarea></label><div class="actions"><button type="button" onclick="addRequestedBusinessField()">＋ Add field</button><button type="button" onclick="removeRequestedBusinessField()">− Remove last field</button></div>
 <p class="muted">Example request: Yield Analysis. “Product code” and “Production code” remain separate requests; the system will not merge them by guesswork.</p>
 <fieldset class="source-picker"><legend>Choose Sources</legend>${explicitDemoMode?`<label class="field">Data mode<select name="sourceMode" onchange="setDatasetSourceMode(this.value,this.form)"><option value="demo" ${mode==='demo'?'selected':''}>DEMO · synthetic data only</option><option value="real" ${mode==='real'?'selected':''} ${window.realSourceSnapshotList().length?'':'disabled'}>Real Oracle metadata${window.realSourceSnapshotList().length?'':' · discover first in Database Connection'}</option></select></label>`:`<input type="hidden" name="sourceMode" value="real"><p class="muted">Source metadata only · choose discovered tables from U-ETL DataBridge. No sample values are used for suggestions.</p>`}<div class="advanced-content">${sourceChoices.length?sourceChoices.map(c=>{const value=mode==='real'?`${c.sourceId}|${c.schema}|${c.table}`:c.id;return `<label class="source-choice"><input type="checkbox" name="sourceIds" value="${safe(value)}" ${selectedSources.includes(value)?'checked':''}><span><b>${safe(mode==='real'?c.sourceName:c.name)}</b><small>${mode==='real'?safe(c.schema+'.'+c.table+' · '+c.columns.length+' columns · read-only metadata'):safe(c.schema+'.'+c.table+' · synthetic example')}</small></span></label>`;}).join(''):mode==='real'?`<p>No discovered metadata yet. <button type="button" onclick="go('copies')">Open U-ETL DataBridge</button> and discover an authorized table first.</p>`:'<p>No synthetic source fixtures available.</p>'}</div></fieldset>
 <details class="advanced-options"><summary>Advanced request details <span class="muted">(optional)</span></summary><div class="advanced-content"><div class="form"><label class="field">Time window start (optional)<input type="datetime-local" name="from" value="${safe(datasetFormDraft.from)}"></label><label class="field">Time window end (optional)<input type="datetime-local" name="to" value="${safe(datasetFormDraft.to)}"></label></div><label class="field">Business filter request (description only; not SQL)<textarea name="filterRequest" maxlength="1000" placeholder="For example: include completed production lots">${safe(datasetFormDraft.filterRequest)}</textarea></label><div class="form"><label class="field">Dataset grain<select name="grain"><option value="unknown" ${datasetFormDraft.grain==='unknown'?'selected':''}>Suggest for me — confirm in next step</option><option value="lot" ${datasetFormDraft.grain==='lot'?'selected':''}>One record per Lot</option><option value="lot_operation" ${datasetFormDraft.grain==='lot_operation'?'selected':''}>One record per Lot / Operation</option><option value="production_event" ${datasetFormDraft.grain==='production_event'?'selected':''}>One record per Production Event</option><option value="user_defined" ${datasetFormDraft.grain==='user_defined'?'selected':''}>Other — describe below</option></select></label><label class="field">Grain rationale / questions<textarea name="grainRationale" maxlength="1000" placeholder="What should the Data Owner confirm?">${safe(datasetFormDraft.grainRationale)}</textarea></label></div></div></details>
<p class="callout">No AI call is made. Dataset creation, review and destination actions in this wizard are prototype-only and do not publish.</p><button class="primary" ${mode==='real'&&!realReady?'disabled':''}>${activeDatasetRequest?'Save changes and rebuild plan':'Continue to suggested plan →'}</button></form></section>`;
}
function datasetCatalogs(request){
 if(request.sourceMode==='real'){
  return request.sources.map(ref=>{const snapshot=window.realSourceSnapshots[`${ref.sourceId}|${ref.schema}|${ref.table}`];if(!snapshot||snapshot.configRevision!==ref.configRevision)return null;return {sourceId:ref.sourceId,sourceRevision:ref.configRevision,sourceName:snapshot.sourceName,schema:ref.schema,table:ref.table,evidence:`Oracle metadata discovery ${snapshot.discoveredAt||''}; metadata only, no sample values used.`,columns:snapshot.columns};}).filter(Boolean);
 }
 return request.sources.map(ref=>{const c=P.connections.find(x=>x.id===ref.sourceId);return {sourceId:ref.sourceId,sourceRevision:c?.revision,sourceName:c?.name||'Demo Source',schema:ref.schema,table:ref.table,evidence:'DEMO synthetic metadata fixture; no database or sample rows.',columns:datasetDemoColumns};});
}
function submitDatasetRequest(event){event.preventDefault();captureDatasetDraft(event.currentTarget);const d=datasetFormDraft,fields=[...new Set(d.businessFields.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];if(!d.name.trim()||!d.purpose.trim()||!fields.length)return notify('Enter Dataset name, purpose and at least one requested business field.');if(fields.length!==d.businessFields.split(/\r?\n/).filter(x=>x.trim()).length)return notify('Remove duplicate requested business fields before continuing.');if(d.from&&d.to&&new Date(d.from)>new Date(d.to))return notify('Time window start must not be after the end.');
 let sources=[];if(d.sourceMode==='real'){const chosen=d.sourceIds.map(key=>window.realSourceSnapshots[key]).filter(Boolean);if(!chosen.length)return notify('Select at least one discovered Source table. Test the connection and discover metadata first.');if(chosen.some(snapshot=>P.connections.find(c=>c.id===snapshot.sourceId)?.revision!==snapshot.configRevision))return notify('A selected Source profile changed; test and discover it again.');sources=chosen.map(snapshot=>({sourceId:snapshot.sourceId,configRevision:snapshot.configRevision,schema:snapshot.schema,table:snapshot.table,discoverySnapshotId:snapshot.discoveredAt||'session-only'}));}else{sources=d.sourceIds.map(id=>(window.datasetWorkflowDemoSources||[]).find(c=>c.id===id)).filter(Boolean).map(c=>({sourceId:c.id,configRevision:1,schema:c.schema,table:c.table}));if(!sources.length)return notify('Select at least one synthetic Source for the Demo preview.');}
 activeDatasetRequest={id:activeDatasetRequest?.id||`dataset-${Date.now()}`,revision:(activeDatasetRequest?.revision||0)+1,name:d.name.trim(),purpose:d.purpose.trim(),businessFields:fields,sources,sourceMode:d.sourceMode,timeWindow:{from:d.from||null,to:d.to||null},filterRequest:d.filterRequest.trim(),grain:d.grain,grainRationale:d.grainRationale.trim(),targetId:d.targetId||null,createdAt:new Date().toISOString(),status:'reviewing'};
 activeDatasetReviews=buildDatasetReview(activeDatasetRequest,datasetCatalogs(activeDatasetRequest));activeDatasetDecisions={};activeDatasetDefinition=null;datasetReviewDrafts={};window.datasetWizardStep=2;S.page='create';S.drawer=false;render();
}
function editDatasetRequest(){if(!activeDatasetRequest)return;datasetFormDraft={name:activeDatasetRequest.name,purpose:activeDatasetRequest.purpose,businessFields:activeDatasetRequest.businessFields.join('\n'),sourceMode:activeDatasetRequest.sourceMode,sourceIds:activeDatasetRequest.sources.map(s=>activeDatasetRequest.sourceMode==='real'?`${s.sourceId}|${s.schema}|${s.table}`:s.sourceId),from:activeDatasetRequest.timeWindow?.from||'',to:activeDatasetRequest.timeWindow?.to||'',filterRequest:activeDatasetRequest.filterRequest||'',grain:activeDatasetRequest.grain,grainRationale:activeDatasetRequest.grainRationale||'',targetId:activeDatasetRequest.targetId||''};datasetSourceMode=datasetFormDraft.sourceMode;window.datasetWizardStep=1;S.page='create';render();}
function invalidateDatasetRequest(reason,sourceId){if(!activeDatasetRequest)return;if(sourceId&&!activeDatasetRequest.sources.some(s=>s.sourceId===sourceId))return;activeDatasetRequest.status='stale';activeDatasetRequest.staleReason=reason;activeDatasetReviews=[];activeDatasetDecisions={};activeDatasetDefinition=null;datasetReviewDrafts={};}
function setDatasetCandidate(field,id){datasetReviewDrafts[field]={...(datasetReviewDrafts[field]||{}),candidateId:id};render();}
function setDatasetReviewReason(field,reason){datasetReviewDrafts[field]={...(datasetReviewDrafts[field]||{}),reason};}
function recordDatasetReview(field,decision){if(!activeDatasetRequest||activeDatasetRequest.status==='stale')return notify('Dataset request or source metadata changed; edit the request to refresh candidates.');const review=activeDatasetReviews.find(r=>r.requestedField===field);if(!review)return notify('Candidate review is unavailable.');const draft=datasetReviewDrafts[field]||{},candidateId=decision==='no_suitable_match'?undefined:(draft.candidateId||review.candidates[0]?.id);try{const result=applyDatasetReview(review,candidateId,decision,activeDatasetRequest.revision,activeDatasetRequest.revision);if(result.reasonRequired&&!String(draft.reason||'').trim())return notify('Enter a rationale for override, rejection or no suitable match.');activeDatasetDecisions[field]={...result,reason:String(draft.reason||'').trim()};activeDatasetRequest.status='reviewing';activeDatasetDefinition=null;render();}catch(e){notify(e.message);}}
function datasetReviewStatus(field){return activeDatasetDecisions[field]?.decision||activeDatasetReviews.find(r=>r.requestedField===field)?.status||'pending';}
function datasetCandidateReviewPanel(){
 if(!activeDatasetRequest)return `<div class="callout">Create a Dataset Request on Overview first. This page accepts real Source metadata only when selected there, and keeps Demo mappings separate.</div>`;
 if(activeDatasetRequest.status==='stale')return `<div class="card"><div class="callout error">Candidate review is stale: ${safe(activeDatasetRequest.staleReason||'Source/request revision changed')}. No prior decision or definition approval is reusable.</div><button onclick="editDatasetRequest()">Edit request and rebuild candidates</button></div>`;
 const req=activeDatasetRequest,readiness=datasetDefinitionReadiness(req,activeDatasetDecisions);
 const rows=activeDatasetReviews.map(review=>{const draft=datasetReviewDrafts[review.requestedField]||{},selectedId=draft.candidateId||review.candidates[0]?.id,selected=review.candidates.find(c=>c.id===selectedId),decision=activeDatasetDecisions[review.requestedField],options=review.candidates.map(c=>`<option value="${safe(c.id)}" ${c.id===selectedId?'selected':''}>${safe(c.sourceName)} · ${safe(c.schema)}.${safe(c.table)}.${safe(c.column)} · ${c.matchingScore} pts${c.ambiguity?' · AMBIGUOUS':''}</option>`).join('');return `<tr><td><b>${safe(review.requestedField)}</b><br>${safe(decision?.decision||review.status)}</td><td>${review.candidates.length?`<select aria-label="Candidate for ${safe(review.requestedField)}" onchange="setDatasetCandidate('${safe(review.requestedField)}',this.value)">${options}</select><p>Source type: ${safe(selected?.sourceType)} · Matching Score: ${selected?.matchingScore??'—'} ranking points (uncalibrated; not probability or %)</p><p>Evidence: ${safe(selected?.evidence.join(' '))}</p><p>Datatype compatibility: ${safe(selected?.datatypeCompatibility)}<br>Join confidence: ${safe(selected?.joinConfidence)}</p>${selected?.ambiguity?`<p class="error">Ambiguous: ${safe(selected.ambiguity)}</p>`:''}<p>Alternatives: ${review.candidates.filter(c=>c.id!==selectedId).map(c=>`${safe(c.schema)}.${safe(c.table)}.${safe(c.column)} (${c.matchingScore} pts)${c.ambiguity?` · AMBIGUOUS: ${safe(c.ambiguity)}`:''}`).join('; ')||'None ranked'}</p>`:`<span>No suitable match. ${safe(review.issue)}</span>`}<label class="field">Reviewer rationale<input aria-label="Rationale ${safe(review.requestedField)}" value="${safe(draft.reason||decision?.reason||'')}" oninput="setDatasetReviewReason('${safe(review.requestedField)}',this.value)" placeholder="Required for override/reject/no match"></label></td><td><div class="actions"><button onclick="recordDatasetReview('${safe(review.requestedField)}','approved')" ${!selected||review.status==='ambiguous'||selected.ambiguity?'disabled':''}>Approve candidate</button><button onclick="recordDatasetReview('${safe(review.requestedField)}','overridden')" ${!selected?'disabled':''}>Override candidate</button><button onclick="recordDatasetReview('${safe(review.requestedField)}','rejected')" ${!selected?'disabled':''}>Reject field</button><button onclick="recordDatasetReview('${safe(review.requestedField)}','no_suitable_match')">No suitable match</button></div></td></tr>`;}).join('');
 return `<section class="card" id="dataset-candidate-review"><div class="callout"><b>${req.sourceMode==='real'?'REAL SOURCE · metadata only':'DEMO · synthetic metadata'}</b> · Request “${safe(req.name)}” revision ${req.revision} · ${req.sources.map(s=>`${safe(s.schema)}.${safe(s.table)} @ config revision ${s.configRevision}`).join(', ')} · no source sample values used for ranking.</div><p>Purpose: ${safe(req.purpose)} · Grain: ${safe(req.grain)} · Time window: ${safe(req.timeWindow?.from||'open')} → ${safe(req.timeWindow?.to||'open')} · Filter request: ${safe(req.filterRequest||'none')}</p><p>Suggestion provider: deterministic metadata/dictionary baseline (${DATASET_DICTIONARY_VERSION}); AI is disabled. Match score is shown as 0–100 ranking points (uncalibrated, not a probability or accuracy percentage). Source type, evidence, datatype compatibility and join confidence remain separate.</p><div class="card tablewrap"><table class="table"><thead><tr><th>Requested business field / state</th><th>Candidate, evidence, alternatives</th><th>Review action</th></tr></thead><tbody>${rows}</tbody></table></div><div class="callout ${readiness.ready?'':'warn'}">${readiness.ready?'All requested fields have review decisions and a grain is selected.':'Definition blockers: '+readiness.blockers.map(safe).join(' · ')}</div><p>Request target preference: ${safe(req.targetId||'not selected')} · target destination remains not configured for real publishing.</p><button class="primary" onclick="approveDatasetDefinition()" ${!readiness.ready||req.status==='stale'?'disabled':''}>Approve Dataset Definition · session prototype only</button>${activeDatasetDefinition?`<div class="callout">Definition review recorded in browser memory at revision ${activeDatasetDefinition.revision}. This does not persist an approval, unlock ETL, or publish.</div>`:''}</section>`;
}
function approveDatasetDefinition(){const readiness=datasetDefinitionReadiness(activeDatasetRequest,activeDatasetDecisions);if(!readiness.ready)return notify(readiness.blockers.join(' '));if(activeDatasetRequest.sourceMode==='real'&&activeDatasetRequest.sources.some(s=>{const snap=window.realSourceSnapshots[`${s.sourceId}|${s.schema}|${s.table}`];return !snap||snap.configRevision!==s.configRevision;}))return notify('Source metadata changed; definition approval blocked.');activeDatasetDefinition={id:`definition-${activeDatasetRequest.id}-r${activeDatasetRequest.revision}`,requestId:activeDatasetRequest.id,revision:activeDatasetRequest.revision,name:activeDatasetRequest.name,grain:activeDatasetRequest.grain,sourceRefs:activeDatasetRequest.sources.map(s=>({...s})),fieldDecisions:JSON.parse(JSON.stringify(activeDatasetDecisions)),dictionaryVersion:DATASET_DICTIONARY_VERSION,provider:'metadata-rule-baseline',approvalState:'prototype-session-only',approvedAt:new Date().toISOString()};activeDatasetRequest.status='definition_approved';render();}
function datasetDiscoveryPanel(){const start=`<div class="callout">Start from a Dataset Request on Overview. Source columns shown here are evidence from the selected Discovery snapshot, not a global dictionary or approval.</div>`;if(!liveSourceDiscovery)return start+`<button onclick="launchLiveSourceDiscovery()">Open Data Sources to Discover authorized metadata</button><p class="muted">Real discovery is optional and read-only; Dataset Requests can also use clearly labeled Demo fixtures.</p>`;return start+`<div class="card"><h3>REAL SOURCE · ${safe(liveSourceDiscovery.schema)}.${safe(liveSourceDiscovery.table)}</h3><p>Metadata snapshot: ${safe(liveSourceDiscovery.discoveredAt||'session-only')} · PK: ${safe(liveSourceDiscovery.keys.filter(k=>k[1]==='P').map(k=>k[2]).join(', ')||'unknown / not visible')} · No sample values enter matching.</p><div class="tablewrap"><table class="table"><thead><tr><th>Column</th><th>Type</th><th>Nullable</th><th>Metadata evidence</th></tr></thead><tbody>${liveSourceDiscovery.columns.map(c=>`<tr><td>${safe(c[0])}</td><td>${safe(c[2])}</td><td>${c[3]==='Y'?'Yes':'No'}</td><td>${safe(liveSourceDiscovery.keys.some(k=>k[2]===c[0])?'Constraint metadata; scope visibility only':'Column name/type metadata')}</td></tr>`).join('')}</tbody></table></div><p class="muted">FK/join confidence remains Unknown until key references, grain, cardinality and data-owner rules have been reviewed. Discovery does not imply Candidate approval or Load readiness.</p><button onclick="launchLiveSourceDiscovery()">Return to existing Data Prep IOT connection card</button></div>`;}
function invalidateDatasetOnSourceEdit(){const id=P.editing;if(id&&activeDatasetRequest?.sources.some(s=>s.sourceId===id))invalidateDatasetRequest('Source connection configuration revision changed',id);}
const baseRealSourceTestProfile=realSourceTestProfile;
realSourceTestProfile=async function(id,options={}){const c=P.connections.find(x=>x.id===id),form=document.querySelector('#connection-form');if(!c)return notify('Save the Oracle Source profile before connecting.');if(form){const d=new FormData(form),changed=c.host!==String(d.get('host')||'').trim()||c.database!==String(d.get('database')||'').trim()||Number(c.port||1521)!==Number(d.get('port'))||c.identifier_type!==d.get('identifier_type')||c.username!==String(d.get('username')||'').trim()||c.protocol!==d.get('protocol');if(changed){c.revision=(c.revision||0)+1;window.dropRealSourceSnapshots(id);realSourceForgetCatalogProfile(id);invalidateDatasetRequest('Oracle connection revision changed before Connect',id);}}realSourceUI.profiles[id]={tested:false,connected:false};const result=await baseRealSourceTestProfile(id);if(options.connectAfterTest&&realSourceUI.profiles[id]?.tested)await realSourceConnectProfile(id);return result;};
async function connectSourceFromForm(id){if(realSourceUI.connecting||realSourceUI.busy)return;const form=document.querySelector('#connection-form');if(!form||!form.reportValidity())return;if(form.elements.engine.value!=='Oracle')return notify('This database engine connector is not available yet. Profile was not tested.');realSourceUI.connecting=true;try{if(!realSourceUI.session){const savedId=saveConnection({connectNow:true});if(!savedId)return;const password=form.elements.password;if(password)password.value='';realSourceUI.promptProfileId=savedId;S.drawer=false;S.page='sources';render();notify('Sign in to the local app, then edit this saved profile, re-enter the Oracle password, and press Connect. The password was not saved.');return;}const savedId=saveConnection({connectNow:true});if(!savedId)return;await realSourceTestProfile(savedId,{connectAfterTest:true});}finally{realSourceUI.connecting=false;}}
const baseOverview=overview;
overview=function(){return datasetRequestPanel()+`<div class="title">Prototype overview · DEMO fixtures only</div>`+baseOverview();};
