if(!explicitDemoMode){
 const demoConnectionDrawer=connectionDrawer;
 connectionDrawer=function(){if(explicitDemoMode)return demoConnectionDrawer();const c=P.connections.find(x=>x.id===P.editing)||{},engine=c.id?engineFor(c):'Oracle',oracle=engine==='Oracle';return `<h2>${c.id?'Edit':'Add'} Source connection</h2><form id="connection-form" onsubmit="event.preventDefault();saveConnection()"><input type="hidden" name="role" value="Source"><div class="form"><label class="field">Connection name<input name="name" required value="${safe(c.name||(oracle?'Data Prep IOT':''))}"></label><label class="field">Database Engine<select name="engine" onchange="toggleConnectionEngine()"><option value="Oracle" ${oracle?'selected':''}>Oracle · Source-safe connector (no Source writes)</option><option value="SQL Server" ${engine==='SQL Server'?'selected':''}>Microsoft SQL Server · connector not available</option><option value="PostgreSQL" ${engine==='PostgreSQL'?'selected':''}>PostgreSQL · connector not available</option><option value="MySQL" ${engine==='MySQL'?'selected':''}>MySQL · connector not available</option><option value="MariaDB" ${engine==='MariaDB'?'selected':''}>MariaDB · connector not available</option></select></label><label class="field">Host / IP<input name="host" required value="${safe(c.host||'')}"></label><label class="field">Port<input name="port" type="number" min="1" max="65535" value="${safe(c.port||(oracle?1521:engine==='SQL Server'?1433:engine==='PostgreSQL'?5432:3306))}"></label><label class="field"><span id="oracle-database-label">${oracle?'Service name/SID':'Database'}</span><input name="database" required value="${safe(c.database||'')}"></label><label class="field" id="oracle-id-type-field" ${oracle?'':'hidden'}>Connection Identifier Type<select name="identifier_type"><option ${c.identifier_type!=='SID'?'selected':''}>Service Name</option><option ${c.identifier_type==='SID'?'selected':''}>SID</option></select></label><label class="field">Username<input name="username" autocomplete="off" required value="${safe(c.username||'')}"></label><label class="field" id="oracle-password-field" ${oracle?'':'hidden'}>Password<input name="password" type="password" autocomplete="new-password" ${oracle?'required':''}></label><label class="field" id="oracle-transport-field" ${oracle?'':'hidden'}>Source transport<select name="protocol"><option value="tcps" ${c.protocol!=='tcp'?'selected':''}>TCPS — certificate validation required</option><option value="tcp" ${c.protocol==='tcp'?'selected':''}>TCP — approved VPN/network only</option></select></label><label class="field">Timeout (seconds)<input name="timeout" type="number" min="1" max="30" value="${c.timeout||30}"></label></div><div id="oracle-acknowledgements" ${oracle?'':'hidden'}><p><label><input name="readonly_ack" type="checkbox" ${oracle?'required':''}> ยืนยันบัญชี/ขอบเขตที่ได้รับอนุญาตให้อ่านอย่างเดียว</label></p><p><label><input name="tcp_ack" type="checkbox"> กรณี TCP: IT/DBA อนุมัติเครือข่าย/VPN แล้ว</label></p></div><div class="actions"><label><input name="remember" type="checkbox" ${c.remember?'checked':''}> Remember connection</label><label><input name="rememberUsername" type="checkbox" ${c.rememberUsername?'checked':''}> Remember username</label>${oracle?`<button type="button" class="primary" onclick="connectSourceFromForm('${safe(c.id||'')}')">Connect</button>`:''}<button class="primary" type="submit">Save connection profile</button></div><p class="callout" id="engine-capability-note">${oracle?'Oracle Source only · Connect verifies login and enables bounded schema/sample reads. It will not modify Source data or schema. Password is sent only over local HTTPS and never saved. Analytics Target publishing is not implemented yet.':'Profile settings only. This engine has no implemented connector yet: Connect/Discovery are unavailable. Do not enter a database password.'}</p></form>`;};
 overview=function(){return datasetRequestPanel()+`<div class="card"><h3>Current capability</h3><p>No Demo records are loaded. Oracle Test/Discovery and metadata-only candidate review are available through the existing Source profile.</p><p>Analytics Target, real ETL, published rows, Quality results and Run History are not configured. No simulated success is shown.</p><button onclick="go('sources')">Open Data Sources</button></div>`;};
 sources=function(){const profiles=P.connections.filter(isOracleProfile);return intro('Oracle Source Setup','Read-only connection and metadata discovery. No Demo Sources or Target profiles are loaded.',`<button class="primary" onclick="P.editing=null;S.drawer='connection';render()">＋ Add Oracle Source</button>`)+`<div class="callout">Real Source mode · credentials are entered in this application over local HTTPS only. Test status is session-only. No Source writes, Analytics Target or ETL.</div>${profiles.length?profiles.map(c=>`<section class="card" data-source-profile="${safe(c.id)}"><b>${safe(c.name)}</b> ${realSourceUI.tested&&realSourceUI.profileId===c.id?'<span class="badge ok">Oracle test passed · read-only</span>':'<span class="badge warn">Oracle · test required</span>'}<p>${safe(c.host||'Host not entered')} / ${safe(c.database||'Service/SID not entered')} · Port ${safe(c.port||1521)}</p><small>Last tested: ${when(c.lastTest)} · revision ${c.revision}</small><div class="actions"><button onclick="connAction('${safe(c.id)}','test')">Test Connection</button><button onclick="connAction('${safe(c.id)}','connect')">Connect</button><button onclick="openConnection('${safe(c.id)}')">Edit</button><button onclick="connAction('${safe(c.id)}','disconnect')">Disconnect / Sign out</button></div></section>`).join(''):`<div class="card"><p>No Oracle Source profile is configured.</p><p>Add the existing Data Prep IOT connection details here; credentials are not imported from the old application.</p></div>`}`;};
 mapping=function(){return intro('Review & Approve','ตรวจคำแนะนำทีละ Business field, เปรียบเทียบ Source/Schema/Table/Column, หลักฐาน และความกำกวม ก่อนบันทึกการอนุมัติแบบ Prototype')+datasetCandidateReviewPanel()+datasetDiscoveryPanel();};
 relationships=function(){return intro('Relationships','No Demo relationships are loaded.')+`<div class="card"><p>Relationship review for Dataset Definitions is not connected yet. No relationship is assumed or approved from the old Demo fixtures.</p><p>Use discovered PK/FK metadata as evidence; confirm grain, cardinality and business meaning with the Data Owner before a multi-source Definition can be approved.</p></div>`;};
 etl=function(){return intro('Transform & Load','Step 04 · เลือก Analytics Target และสั่ง Load หลัง Definition ผ่านการอนุมัติและ Backend พร้อม')+`<div class="card"><h3>ยังเริ่ม Load ไม่ได้</h3><p>Analytics Target จริงและ ETL Worker ยังไม่ได้เชื่อมต่อ ขั้นนี้จึงถูกปิดไว้ ไม่มี simulated progress หรือ ETL Success ปลอม</p><p>สิ่งที่ต้องพร้อมก่อน: Test Target แยกจาก Source, durable Backend/Worker, approved Dataset Definition, transform rules, run-boundary/idempotency/watermark tests</p><button onclick="go('mapping')">กลับไปตรวจ Dataset Definition</button><button onclick="go('sources')">ตรวจ Source connections</button></div>`;};
 explorer=function(){return intro('Data Explorer','No real Analytics Target is connected.')+`<div class="card">No published data is available. Source sample preview remains in the read-only Data Sources session and is not an Analytics Dataset.</div>`;};
 quality=function(){return intro('Data Quality','No published Run results are available.')+`<div class="card">Quality counts and quarantine are not shown until a real Backend Run publishes to an approved Test Target.</div>`;};
 runs=function(){return intro('Run History','No durable Backend job history is configured.')+`<div class="card">There are no real Runs. Demo history and seeded Run records were cleared from this browser profile.</div>`;};
 settings=function(){return intro('Settings','Runtime configuration and pending decisions')+`<div class="grid c2"><div class="card"><h3>AI</h3><p>Disabled; no AI calls are made.</p></div><div class="card"><h3>Backend</h3><p>Local Oracle Source read-only spike only. Registry, Analytics Target, durable Worker and real ETL are not configured.</p></div><div class="card"><h3>Security</h3><p>Source password is transient and not stored. Test/Discovery session is memory-only.</p></div><div class="card"><h3>Next confirmations</h3><p>DBA: Source grants/network/query budget. Owner/IT: Test Registry/Target, runtime identity, secret store/auth policy. Data Owner: grain, keys and field meanings.</p></div></div>`;};
 toggleConnectionEngine=function(){const f=document.querySelector('#connection-form');if(!f)return;const e=f.elements.engine.value,o=e==='Oracle';document.querySelector('#oracle-id-type-field').hidden=!o;document.querySelector('#oracle-password-field').hidden=!o;document.querySelector('#oracle-transport-field').hidden=!o;document.querySelector('#oracle-acknowledgements').hidden=!o;f.elements.readonly_ack.required=o;f.elements.password.required=o;document.querySelector('#oracle-database-label').textContent=o?'Service name/SID':'Database';document.querySelector('#engine-capability-note').textContent=o?'Oracle Source only · Connect verifies login and enables bounded schema/sample reads. It will not modify Source data or schema. Password is sent only over local HTTPS and never saved. Analytics Target publishing is not implemented yet.':'Profile settings only. This engine has no implemented connector yet: Connect/Discovery are unavailable. Do not enter a database password.';if(e==='SQL Server')f.elements.port.value=1433;else if(e==='PostgreSQL')f.elements.port.value=5432;else if(e==='MySQL'||e==='MariaDB')f.elements.port.value=3306;else f.elements.port.value=1521;};
 sources=function(){const profiles=P.connections.filter(c=>c.role==='Source'&&!isStoredDemoConnection(c));return intro('Connect databases','เพิ่มและบันทึก Source profiles ได้หลายรายการ แล้วทดสอบ/ค้นพบ metadata ภายใต้บัญชีของแต่ละ Source',`<button class="primary" onclick="P.editing=null;S.drawer='connection';render()">＋ Add Source connection</button>`)+`<div class="callout">Step 01 · Connections เก็บเฉพาะรายละเอียด profile ที่ไม่ใช่รหัสผ่าน Password ไม่ถูกบันทึก; Oracle ใช้ read-only connector ส่วน Engine อื่นยังเป็น profile เท่านั้น</div>${profiles.length?profiles.map(c=>{const oracle=isOracleProfile(c),hasSnapshot=window.sourceHasCurrentSnapshot(c.id);return `<section class="card" data-source-profile="${safe(c.id)}"><b>${safe(c.name)}</b> ${oracle?(realSourceUI.tested&&realSourceUI.profileId===c.id?'<span class="badge ok">Oracle test passed · read-only</span>':hasSnapshot?'<span class="badge ok">Metadata discovered in this session</span>':'<span class="badge warn">Oracle · test required</span>'):'<span class="badge warn">'+safe(engineFor(c))+' · connector not implemented</span>'}<p>${safe(c.host||'Host not entered')} / ${safe(c.database||'Database not entered')} · Port ${safe(c.port||'—')}</p><small>${oracle?'Oracle read-only connector':'Profile only; no database connection'} · revision ${c.revision||1}</small>${oracle?`<small>Last tested: ${when(c.lastTest)}</small><div class="actions"><button onclick="connAction('${safe(c.id)}','test')">Test Connection</button><button onclick="connAction('${safe(c.id)}','connect')">Connect</button><button onclick="openConnection('${safe(c.id)}')">Edit</button><button onclick="connAction('${safe(c.id)}','disconnect')">Disconnect / Sign out</button></div>${hasSnapshot?`<small>Session metadata: ${window.realSourceSnapshotList().filter(s=>s.sourceId===c.id).length} discovered object(s)</small>`:''}`:`<div class="actions"><button onclick="openConnection('${safe(c.id)}')">Edit profile</button></div>`}</section>`;}).join(''):`<div class="card"><p>No Source profile is configured.</p><p>Use Add Source connection to configure Oracle or record an engine profile for later implementation.</p></div>`}`;};
 overview=function(){return `<div class="workflow-heading"><div><span class="eyebrow">U-ETL WORKSPACE</span><h2>Build a Dataset for analysis</h2><p>เชื่อมแหล่งข้อมูล → ระบุข้อมูลธุรกิจที่ต้องการ → ตรวจคำแนะนำ → โหลดเมื่อ Target พร้อม</p></div><span class="badge warn">Prototype · AI disabled · no real Load</span></div>`+datasetRequestPanel()+`<section class="card capability-summary"><h3>Current capability</h3><p>บันทึก Source profile ได้หลายรายการ และค้นพบ Oracle metadata แบบ read-only ในหน้าเดิม; Engine อื่นยังไม่มี Connector</p><p>คำแนะนำปัจจุบันเป็น rule-based ไม่ใช่ AI. Analytics Target, durable approval และ real ETL ยังไม่พร้อม</p><button onclick="go('sources')">Manage Source connections</button></section>`;};
}
const renderWithPrototypeChrome=render;
function workflowStageNav(active){const sourceCount=P.connections.filter(c=>c.role==='Source'&&!isStoredDemoConnection(c)).length,snapshotCount=window.realSourceSnapshotList().length,reviewCount=Object.keys(activeDatasetDecisions).length;const stages=[['sources','01','Connect sources',`${sourceCount} saved profile(s) · ${snapshotCount} metadata snapshot(s)`],['overview','02','Create Dataset',activeDatasetRequest?safe(activeDatasetRequest.name):'Name, purpose and requested fields'],['mapping','03','Review & approve',activeDatasetRequest?`${reviewCount}/${activeDatasetRequest.businessFields.length} field decisions`:'Awaiting Dataset Request'],['etl','04','Transform & Load','Target/Worker not configured']];return `<nav class="workflow-nav" aria-label="Dataset workflow">${stages.map(([page,num,title,detail])=>`<button class="workflow-stage ${active===page?'active':''}" aria-current="${active===page?'step':'false'}" onclick="go('${page}')"><span class="workflow-number">${num}</span><span><b>${title}</b><small>${detail}</small></span><span class="workflow-arrow">${page==='etl'?'›':'→'}</span></button>`).join('')}</nav>`;}
render=function(){renderWithPrototypeChrome();if(!explicitDemoMode){document.querySelector('.wizard')?.remove();document.querySelector('.toolbar select[aria-label="Page state"]')?.closest('.toolbar')?.remove();const main=document.querySelector('.content');if(['sources','overview','mapping','etl'].includes(S.page))main.insertAdjacentHTML('afterbegin',workflowStageNav(S.page));}};
bindScope();if(sync.history.some(r=>r.state==='running')){for(const r of sync.history.filter(r=>r.state==='running')){r.state='failed';r.result='Browser interrupted before Publish; reconnect and Retry';r.tables.forEach(t=>{if(t.state==='running')t.state='failed';});}sync.active=null;}
// Owner UI-reset Prototype: the normal application exposes four destinations.
window.datasetWizardStep=window.datasetWizardStep||1;
window.datasetWorkflowDemoSources=window.datasetWorkflowDemoSources||[
 {id:'demo-mes-process',name:'MES · Example source',schema:'SYNTHETIC_MES',table:'PROCESS_EVENT',columns:datasetDemoColumns,selected:true},
 {id:'demo-qc-inspection',name:'QC · Example source',schema:'SYNTHETIC_QC',table:'INSPECTION',columns:[['LOT_NUMBER',1,'VARCHAR','N'],['OUTPUT_QTY',2,'NUMBER','Y'],['REJECT_QTY',3,'NUMBER','Y'],['PACKAGE_CODE',4,'VARCHAR','Y'],['CUSTOMER_CODE',5,'VARCHAR','Y']],selected:false}
];
window.datasetWorkflowTargets=window.datasetWorkflowTargets||[];
window.datasetWorkflowItems=window.datasetWorkflowItems||[];
window.datasetWorkflowActivity=window.datasetWorkflowActivity||[];
window.datasetWorkflowGrainConfirmed=window.datasetWorkflowGrainConfirmed||false;
function datasetGrainSuggestion(){const text=`${activeDatasetRequest?.purpose||''} ${(activeDatasetRequest?.businessFields||[]).join(' ')}`.toLowerCase();return /process|operation|step|etch|yield drop|yield loss|ขั้นตอน|กระบวนการ/.test(text)?'lot_operation':/final|overall|lot yield|final yield|ผลผลิตรวม|yield ของ lot/.test(text)?'lot':(activeDatasetRequest?.businessFields||[]).some(x=>/process|operation|equipment|machine/i.test(x))?'lot_operation':'lot';}
function addRequestedBusinessField(){const el=document.querySelector('[name=businessFields]');if(el){el.value+=(el.value.trim()?'\n':'')+'New business field';captureDatasetDraft(el.form);el.focus();el.setSelectionRange(el.value.length,el.value.length);}}
function removeRequestedBusinessField(){const el=document.querySelector('[name=businessFields]');if(el){const lines=el.value.split(/\r?\n/);lines.pop();el.value=lines.join('\n');captureDatasetDraft(el.form);el.focus();}}
function updateDatasetGrain(value){if(!activeDatasetRequest)return;activeDatasetRequest.grain=value;window.datasetWorkflowGrainConfirmed=true;activeDatasetRequest.grainRationale='Owner confirmed the suggested grain in the UI Prototype.';activeDatasetDefinition=null;render();}
function approveDatasetRelationships(){if(!activeDatasetRequest)return;activeDatasetRequest.relationshipReview={approved:true,source:'human confirmation in UI Prototype'};activeDatasetDefinition=null;render();}
function advanceDatasetWizard(step){window.datasetWizardStep=step;S.page='create';render();}
function confirmDatasetPlan(){if(!activeDatasetRequest)return;const readiness=datasetDefinitionReadiness(activeDatasetRequest,activeDatasetDecisions);if(!window.datasetWorkflowGrainConfirmed||activeDatasetRequest.grain==='unknown')return notify('Confirm what one row represents before continuing.');if(!readiness.ready)return notify(readiness.blockers.join(' '));approveDatasetDefinition();if(activeDatasetDefinition){window.datasetWizardStep=3;render();}}
function syntheticPreviewMarkup(){const fields=activeDatasetRequest?.businessFields||[];const values={'lot number':['LOT-DEMO-001','LOT-DEMO-002'],'lot no':['LOT-DEMO-001','LOT-DEMO-002'],'input quantity':['120','100'],'input qty':['120','100'],'output quantity':['116','96'],'output qty':['116','96'],'package code':['PKG-A','PKG-B'],'customer code':['CUST-DEMO','CUST-DEMO'],'product code':['PROD-A','PROD-B'],'production code':['ROUTE-1','ROUTE-2'],'production area':['AREA-01','AREA-02'],'process step':['ETCH','TEST'],'equipment':['EQ-DEMO-01','EQ-DEMO-02']};return `<div class="tablewrap"><table class="table"><thead><tr>${fields.map(f=>`<th>${safe(f)}</th>`).join('')}</tr></thead><tbody>${[0,1].map(i=>`<tr>${fields.map(f=>`<td>${safe((values[f.toLowerCase()]||['EXAMPLE-A','EXAMPLE-B'])[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function datasetWizardChrome(step){const labels=['Request','Review plan','Preview','Publish'];return `<div class="workflow-heading"><div><span class="eyebrow">AI DATA BRIDGE · STEP ${step} OF 4</span><h2>${labels[step-1]}</h2><p>กำหนดข้อมูลที่ต้องการ ตรวจคำแนะนำและอนุมัติก่อนสร้าง Dataset</p></div><span class="badge warn">Prototype · AI is not connected</span></div><nav class="wizard-steps" aria-label="AI Data Bridge steps">${labels.map((x,i)=>`<span class="wizard-step ${i+1===step?'current':i+1<step?'done':''}">${i+1}. ${x}</span>`).join('')}</nav>`;}
function create(){const step=window.datasetWizardStep||1;let body='';if(step===1)body=datasetRequestPanel();else if(!activeDatasetRequest)body=`<div class="card"><p>Create a Dataset request first.</p><button class="primary" onclick="advanceDatasetWizard(1)">Start at Step 1</button></div>`;else if(step===2){const suggestion=datasetGrainSuggestion(),multi=activeDatasetRequest.sources.length>1,readiness=datasetDefinitionReadiness(activeDatasetRequest,activeDatasetDecisions),reviewPanel=datasetCandidateReviewPanel().replace(/<p>Request target preference:[\s\S]*?<\/p>/,'').replace(/<button class="primary" onclick="approveDatasetDefinition\(\)"[^>]*>Approve Dataset Definition · session prototype only<\/button>/,'');body=`<div class="card"><div class="callout"><b>Suggested row meaning</b><p>หนึ่งแถวแทน <b>${suggestion==='lot_operation'?'หนึ่ง Lot ในหนึ่งขั้นตอนการผลิต':'หนึ่ง Lot'}</b></p><p>ข้อเสนอจาก Purpose/ฟิลด์ที่กรอก ใช้เป็นแนวทางเท่านั้น กรุณายืนยันหรือเลือกข้ออื่น</p><label class="field">One row represents<select aria-label="Dataset grain proposal" onchange="updateDatasetGrain(this.value)"><option value="unknown" ${activeDatasetRequest.grain==='unknown'?'selected':''}>Choose / confirm</option><option value="lot" ${activeDatasetRequest.grain==='lot'?'selected':''}>One record per Lot</option><option value="lot_operation" ${activeDatasetRequest.grain==='lot_operation'?'selected':''}>One record per Lot / process step</option><option value="production_event" ${activeDatasetRequest.grain==='production_event'?'selected':''}>One record per Production Event</option></select></label></div>${multi?`<div class="card"><h3>Suggested relationship plan</h3><p>Candidate join: Lot number across selected sources. Key and cardinality are not verified by this simulation.</p><button onclick="approveDatasetRelationships()">Confirm this relationship proposal (simulation)</button>${activeDatasetRequest.relationshipReview?.approved?'<span class="badge ok">Confirmed for prototype review</span>':''}</div>`:''}<div class="title">Suggested fields and source columns</div>${reviewPanel}<div class="actions"><button onclick="advanceDatasetWizard(1)">Back · Edit request</button><button class="primary" onclick="confirmDatasetPlan()">${activeDatasetDefinition?'Continue to Preview →':'Approve reviewed plan & continue'}</button></div><p class="muted">Approval exists only in this browser session; it is not a durable Mapping approval.</p></div>`;}else if(step===3){const real=activeDatasetRequest.sourceMode==='real';body=`<div class="card"><div class="callout ${real?'warn':''}">${real?'REAL SOURCE · metadata only. No real row preview is included or mixed with synthetic rows. Use the explicitly bounded sample in Connections separately.':'DEMO · Synthetic preview only. No factory rows are shown or read.'}</div><h3>What one row means</h3><p>${activeDatasetRequest.grain==='lot_operation'?'One Lot at one production operation.':'One record per '+safe(activeDatasetRequest.grain||'confirmed grain')+'.'}</p><h3>Requested fields</h3><p>${activeDatasetRequest.businessFields.map(safe).join(' · ')}</p><h3>${real?'Preview unavailable for real metadata':'Example output rows'}</h3>${real?'<p>Real Target preview is not implemented; this view will not claim a successful dataset build.</p>':syntheticPreviewMarkup()}<h3>Prototype checks</h3><ul><li>Requested fields: ${activeDatasetRequest.businessFields.length} · all reviewed</li><li>Join plan: ${activeDatasetRequest.sources.length>1?(activeDatasetRequest.relationshipReview?.approved?'reviewer-confirmed for demo':'not confirmed'):'single source · no join required'}</li><li>Duplicate/key/required-field checks: illustrative only, not run against a database</li></ul><button onclick="advanceDatasetWizard(2)">Back · Edit plan</button><button class="primary" onclick="advanceDatasetWizard(4)">Continue to Destination →</button></div>`;}else{const targets=window.datasetWorkflowTargets;body=`<div class="card"><div class="callout warn">SIMULATION ONLY · No Analytics Target is connected. Create Dataset will not create a database/table, publish rows, or schedule updates.</div><label class="field">Department Analytics Target<select id="dataset-target"><option value="demo-target">Synthetic target · preview only</option>${targets.map(t=>`<option value="${safe(t.id)}">${safe(t.name)} · profile only, not connected</option>`).join('')}</select></label><label class="field">Dataset / table name<input id="dataset-table-name" value="${safe(activeDatasetRequest.name.replace(/[^a-zA-Z0-9_]+/g,'_').toLowerCase())}" maxlength="128"></label><label class="field">Update schedule<select id="dataset-cadence"><option>Manual</option><option>Every 5 minutes (simulation)</option><option>Every 15 minutes (simulation)</option><option>Every 1 hour (simulation)</option></select></label><p>Current Target status: <b>Not connected</b> · Update schedule is a saved prototype preference only; Scheduler is not implemented.</p><h3>Review before Create</h3><p>${safe(activeDatasetRequest.name)} · ${activeDatasetRequest.sources.length} source(s) · ${activeDatasetRequest.businessFields.length} field(s) · ${safe(activeDatasetRequest.grain)}</p><div class="actions"><button onclick="advanceDatasetWizard(3)">Back · Preview</button><button class="primary" onclick="createDatasetSimulation()">Create Dataset (simulation)</button></div></div>`;}return datasetWizardChrome(step)+body;}
function createDatasetSimulation(){if(!activeDatasetRequest||!activeDatasetDefinition)return notify('Review and approve the Dataset plan before creating it.');const table=document.getElementById('dataset-table-name').value.trim();if(!table)return notify('Enter a Dataset/table name.');const cadence=document.getElementById('dataset-cadence').value,target=document.getElementById('dataset-target').value;const item={id:`dataset-${Date.now()}`,name:activeDatasetRequest.name,table,purpose:activeDatasetRequest.purpose,fields:[...activeDatasetRequest.businessFields],grain:activeDatasetRequest.grain,sourceMode:activeDatasetRequest.sourceMode,target,cadence,status:'Created (simulation only)',createdAt:new Date().toISOString(),published:false};window.datasetWorkflowItems.unshift(item);window.datasetWorkflowActivity.unshift({at:item.createdAt,title:`${item.name} created`,detail:'Prototype simulation only · no Target publish or scheduled update',state:'Simulated'});S.notice='Dataset created in this browser session only; nothing was written to a database.';window.datasetWizardStep=1;S.page='datasets';render();}
function datasets(){const items=window.datasetWorkflowItems;return `<div class="intro"><div><h2>Data Set</h2><p class="muted">รายการ Dataset และสถานะการสร้าง</p></div><div class="actions"><button onclick="S.page='activity';render()">Activity history</button><button class="primary" onclick="startDatasetWizard()">＋ New Dataset</button></div></div><div class="tablewrap card dataset-list"><table class="table"><thead><tr><th>Dataset</th><th>Status</th><th>Updated</th><th>Update policy</th><th>Actions</th></tr></thead><tbody>${items.length?items.map((x,i)=>`<tr><td><b>${safe(x.name)}</b><br><small class="muted">${safe(x.purpose)}</small></td><td><span class="badge warn">Draft · session only</span></td><td>—</td><td>${safe(x.cadence||'Manual')} · prototype preference</td><td><button onclick="startDatasetWizard()">New request</button> <button onclick="document.getElementById('dataset-detail-${i}').hidden=false">View</button></td></tr><tr id="dataset-detail-${i}" hidden><td colspan="5">${safe(x.fields.join(' · '))} · Grain: ${safe(x.grain)} · Target publish: not configured</td></tr>`).join(''):`<tr><td colspan="5" class="empty-cell">No Dataset requests yet. Create one in AI Data Bridge.</td></tr>`}</tbody></table></div><p class="callout">No Analytics Target is configured. Requests and approvals are session-only; nothing has been published to a database.</p>`;}
function startDatasetWizard(){window.datasetWizardStep=1;activeDatasetRequest=null;activeDatasetReviews=[];activeDatasetDecisions={};activeDatasetDefinition=null;datasetReviewDrafts={};datasetFormDraft={name:'',purpose:'',businessFields:'',sourceMode:explicitDemoMode?'demo':'real',sourceIds:[],from:'',to:'',filterRequest:'',grain:'unknown',grainRationale:'',targetId:''};datasetSourceMode=explicitDemoMode?'demo':'real';window.datasetWorkflowGrainConfirmed=false;S.page='create';render();}
function activity(){const entries=[...window.datasetWorkflowActivity];for(const c of P.connections.filter(x=>x.role==='Source'&&!isStoredDemoConnection(x))){if(c.status==='failed')entries.push({at:c.lastTest||'',title:`${c.name}: Connection test failed`,detail:c.message||'See Connections for details',state:'Needs attention'});}return `<div class="workflow-heading"><div><span class="eyebrow">ACTIVITY</span><h2>Activity</h2><p>งานจำลอง สถานะการเชื่อมต่อ และเหตุการณ์ที่ต้องตรวจ</p></div></div>${entries.length?entries.map(x=>`<article class="card activity-entry"><b>${safe(x.title)}</b> <span class="badge warn">${safe(x.state)}</span><p>${safe(x.detail)}</p><small>${safe(x.at)}</small></article>`).join(''):`<div class="card empty-state"><h3>ยังไม่มีกิจกรรม</h3><p>ผลการสร้าง Dataset แบบจำลองหรือปัญหาการเชื่อมต่อจะแสดงที่นี่</p></div>`}<p class="callout">Activity ใน Prototype ไม่ใช่ durable job history; งานจริงยังไม่มี Target/Worker</p>`;}
function startTargetProfile(){S.drawer='target-profile';render();}
function saveTargetProfile(){const form=document.getElementById('target-profile-form');if(!form.reportValidity())return;const d=new FormData(form);window.datasetWorkflowTargets.unshift({id:`target-${Date.now()}`,name:String(d.get('name')).trim(),engine:d.get('engine'),host:String(d.get('host')).trim(),database:String(d.get('database')).trim(),kind:'profile-only',status:'Not tested; Target connector unavailable'});S.drawer=false;render();}
function targetProfileDrawer(){return `<div class="overlay" onclick="S.drawer=false;render()"></div><aside class="drawer"><button class="close" onclick="S.drawer=false;render()">×</button><h2>Add Analytics Target profile</h2><form id="target-profile-form" onsubmit="event.preventDefault();saveTargetProfile()"><label class="field">Connection name<input name="name" required maxlength="100"></label><label class="field">Database engine<select name="engine"><option>SQL Server</option><option>Oracle</option><option>PostgreSQL</option><option>MySQL</option><option>MariaDB</option></select></label><label class="field">Server / Host<input name="host" required></label><label class="field">Database<input name="database" required></label><p class="callout warn">Profile only. Test Connection / write is unavailable in this UI scope; no password is accepted or saved.</p><button class="primary">Save target profile</button></form></aside>`;}
const resetUiDrawer=drawer;
let localDataPreview=null;
function storedDataPreviewDrawer(){const result=localDataPreview;if(!result)return `<div class="overlay" onclick="closeStoredDataPreview()"></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="Stored table data"><button class="close" onclick="closeStoredDataPreview()">×</button><h2>Loading stored data…</h2></aside>`;const headers=result.columns.map(column=>`<th>${safe(column)}</th>`).join(''),rows=result.rows.map(row=>`<tr>${row.map(value=>`<td>${value===null?'<span class="muted">NULL</span>':safe(typeof value==='object'?JSON.stringify(value):String(value))}</td>`).join('')}</tr>`).join('');return `<div class="overlay" onclick="closeStoredDataPreview()"></div><aside class="drawer source-manager-drawer stored-data-drawer" role="dialog" aria-modal="true" aria-label="Stored table data"><button class="close" aria-label="Close data preview" onclick="closeStoredDataPreview()">×</button><h2>Stored data · ${safe(result.schema)}.${safe(result.object)}</h2><p class="muted">Local SQLite · ${safe(result.target_rows)} rows stored · Preview limited to ${safe(result.preview_limit)} rows. This does not query Oracle.</p><div class="tablewrap"><table class="table stored-data-table"><thead><tr>${headers}</tr></thead><tbody>${rows||`<tr><td colspan="${Math.max(result.columns.length,1)}">No rows loaded yet.</td></tr>`}</tbody></table></div></aside>`;}
drawer=function(){if(S.drawer==='source-manager'){const c=P.connections.find(x=>x.id===realSourceUI.expandedProfileId);if(!c)return '';return `<div class="overlay" onclick="closeSourceManager()"></div><aside class="drawer source-manager-drawer" role="dialog" aria-modal="true" aria-label="Manage Source connection"><button class="close" aria-label="Close manager" onclick="closeSourceManager()">×</button><h2>Manage · ${safe(c.name)}</h2><p class="muted">Oracle Source · read-only metadata and explicitly requested bounded preview</p><div id="real-source-manager-mount"></div></aside>`;}if(S.drawer==='local-data-preview')return storedDataPreviewDrawer();return S.drawer==='target-profile'?targetProfileDrawer():resetUiDrawer();};
async function viewStoredData(sourceId,schema,objectName){localDataPreview=null;S.drawer='local-data-preview';render();try{const query=new URLSearchParams({profile_id:sourceId,schema,object:objectName,limit:'100'});localDataPreview=await realApi(`local-target/preview?${query}`);}catch(error){localDataPreview={error:error.message};}if(localDataPreview?.error){const message=localDataPreview.error;S.drawer=false;localDataPreview=null;render();notify(message);return;}if(S.drawer==='local-data-preview')render();}
function closeStoredDataPreview(){S.drawer=false;localDataPreview=null;render();}
const resetConnectionsScreen=sources;
sources=function(){const base=resetConnectionsScreen();const targets=window.datasetWorkflowTargets;return base+`<section class="target-connection-section"><div class="section-heading"><div><h2>Analytics Target</h2><p>ปลายทางของแผนก · แยกจาก Source</p></div><button onclick="startTargetProfile()">＋ Add Target profile</button></div><div class="callout warn">ยังไม่มี Target connector ในระบบ · โปรไฟล์ที่บันทึกเป็นข้อมูลตั้งค่าเท่านั้น ไม่ได้เชื่อมต่อหรือทดสอบจริง</div>${targets.length?targets.map(t=>`<article class="card"><b>${safe(t.name)}</b> <span class="badge warn">Not tested</span><p>${safe(t.engine)} · ${safe(t.host)} / ${safe(t.database)}</p><small>Profile only · no write capability</small></article>`).join(''):`<div class="card">No Analytics Target profile configured.</div>`}</section>`;};
function openSourceSignIn(id){realSourceUI.promptProfileId=id;realSourceUI.expandedProfileId=id;S.page='sources';S.drawer='source-manager';render();}
 async function manageSourceConnection(id){const c=P.connections.find(x=>x.id===id);if(!isOracleProfile(c))return notify('This engine profile has no implemented connector yet. No connection was attempted.');if(location.protocol!=='https:')return notify('Oracle access is available only at https://localhost:8443/. No credentials were sent.');if(!realSourceUI.session)return openSourceSignIn(id);if(realSourceUI.expandedProfileId===id&&S.drawer==='source-manager')return closeSourceManager();if(!realSourceUI.profiles[id]?.connected)return notify('Connect this Source profile before opening its catalog.');realSourceActivateProfile(id);realSourceUI.expandedProfileId=id;realSourceUI.tested=true;realSourceUI.notice='Opening saved catalog…';S.drawer='source-manager';render();await realSourceRestoreCatalog(id);if(realSourceUI.expandedProfileId===id&&S.drawer==='source-manager')render();}
function closeSourceManager(){S.drawer=false;realSourceUI.expandedProfileId=null;render();}
sources=function(){
 const rows=P.connections.filter(c=>c.role==='Source').map(c=>{const oracle=isOracleProfile(c),profileState=realSourceUI.profiles[c.id]||{},connected=oracle&&realSourceUI.session&&(profileState.connected||c.status==='connected');let state;
   if(connected)state='<span class="badge ok" title="Profile ready for bounded read-only operations; no persistent Oracle socket">Connected</span>';
  else if(oracle&&c.status==='testing')state='<span class="badge warn">Testing…</span>';
  else if(oracle&&c.status==='failed')state='<span class="badge err">Test failed</span>';
   else if(oracle&&(profileState.tested||c.status==='test_passed'))state='<span class="badge warn">Test passed · disconnected</span>';
   else if(oracle)state='<span class="badge warn">Not connected</span>';
  else state=`<span class="badge warn">${safe(engineFor(c))} · profile only</span>`;
   const actions=oracle?`${connected?`<button ${realSourceUI.busy?'disabled':''} onclick="connAction('${safe(c.id)}','disconnect')">Disconnect</button><button ${realSourceUI.busy?'disabled':''} onclick="manageSourceConnection('${safe(c.id)}')">${S.drawer==='source-manager'&&realSourceUI.expandedProfileId===c.id?'Close':'Manage'}</button>`:`<button ${realSourceUI.busy?'disabled':''} onclick="connAction('${safe(c.id)}','connect')">Connect</button>`}<button ${realSourceUI.busy?'disabled':''} onclick="openConnection('${safe(c.id)}')">Edit</button>`:`<button onclick="openConnection('${safe(c.id)}')">Edit</button>`;
   return `<article class="connection-row" data-source-profile="${safe(c.id)}"><div class="connection-cells"><div><b>${safe(c.name)}</b></div><div><span>${safe(engineFor(c))} / ${safe(c.database||'—')}</span></div><div>${state}<small class="muted">${safe(c.host||'—')}${c.port?` · ${safe(c.port)}`:''}</small>${c.status==='failed'&&c.message?`<small class="error">${safe(c.message)}</small>`:''}</div><div><span>Not collected</span></div><div><span>—</span><small class="muted">Not configured</small></div><div class="actions">${actions}</div></div>${realSourceUI.expandedProfileId===c.id?`<div class="real-source-mount"></div>`:''}</article>`;
 }).join('');
  return `<div class="intro connection-intro"><div><h2>Database Connection</h2><p class="muted">ฐานข้อมูลต้นทางของ IT · จัดการการเชื่อมต่อและเลือก Schema/Table เพื่อ Discovery แบบ read-only</p></div><button class="primary" onclick="openConnection()">＋ New connection</button></div><div class="connection-table-scroll"><div class="connection-table-inner"><div class="connection-table-head"><span>Source connection</span><span>Database</span><span>Connection</span><span>Collection</span><span>Last sync / Next run</span><span>Actions</span></div><div class="connection-list">${rows||'<div class="connection-empty">No saved connections · กด + New connection เพื่อเริ่มต้น</div>'}</div></div></div><section class="connection-copy-card"><h3>สำเนาที่ดึงสำเร็จแล้ว</h3><p>ยังไม่มีข้อมูลที่คัดลอกไปเก็บใน U-ETL DataBridge</p><button onclick="go('copies')">เปิด U-ETL DataBridge</button></section>`;
};
function beginDatasetFromSnapshot(key){const snap=window.realSourceSnapshots?.[key];if(!snap)return notify('Metadata snapshot is no longer available. Discover the object again.');startDatasetWizard();datasetFormDraft.sourceMode='real';datasetFormDraft.sourceIds=[key];datasetSourceMode='real';S.page='create';render();}
function collectionPrimaryKeyMarkup(snapshot){const keys=snapshot.keys;if(!Array.isArray(keys))return '<span class="muted">Not discovered</span>';const groups=new Map();for(const key of keys){if(!Array.isArray(key)||key[1]!=='P')continue;const constraint=String(key[0]||'Primary key');if(!groups.has(constraint))groups.set(constraint,[]);const column=String(key[2]||'');if(column&&!groups.get(constraint).some(item=>item.column===column))groups.get(constraint).push({column,position:Number(key[3])||0});}if(!groups.size)return '<span class="muted">No primary key</span>';return [...groups].map(([name,columns])=>{columns.sort((a,b)=>a.position-b.position);return `<span class="primary-key-entry"><strong>${safe(name)}</strong><small>Key columns: ${columns.map(item=>safe(item.column)).join(', ')}</small></span>`;}).join('');}
function copies(){
 const snapshots=window.realSourceSnapshotList?.()||[];
 const valid=snapshots.filter(s=>P.connections.some(c=>c.id===s.sourceId&&c.revision===(s.configRevision||1)));
 const rows=valid.map(s=>{const c=P.connections.find(x=>x.id===s.sourceId),key=`${s.sourceId}|${s.schema}|${s.table}`;return `<tr><td>${safe(s.sourceName||c?.name||'Source')}</td><td>${safe(c?.database||'—')}</td><td>${safe(s.schema)}</td><td>${safe(s.table)}<br><small class="muted">${(s.columns||[]).length} columns · metadata only</small></td><td class="primary-key-cell">${collectionPrimaryKeyMarkup(s)}</td><td data-local-load-rows="${safe(key)}">Not copied</td><td data-local-load-storage="${safe(key)}">—</td><td data-local-load-time="${safe(key)}">Not collected</td><td><div class="actions"><button class="stored-data-view" data-stored-view="${safe(key)}" disabled onclick="viewStoredData('${safe(s.sourceId)}','${safe(s.schema)}','${safe(s.table)}')">View data</button><button onclick="beginDatasetFromSnapshot('${safe(key)}')">Use in AI Data Bridge</button><button class="table-load-run" onclick="runLocalExtractLoad('${safe(s.sourceId)}','${safe(s.schema)}','${safe(s.table)}')" ${s.keys?.some(k=>k[1]==='P')?'':'disabled title="Primary Key required to prevent duplicate rows"'}>Load data</button></div></td></tr>`;}).join('');
 return `<div class="intro"><div><h2>U-ETL DataBridge</h2><p class="muted">พื้นที่รวมข้อมูลต้นทางที่ค้นพบและสถานะการจัดเก็บ</p></div><button disabled title="Production storage settings are not configured">Storage settings</button></div><section class="card storage-summary"><label class="field">Source connection<select aria-label="Source connection filter"><option>All connections</option>${P.connections.filter(c=>c.role==='Source').map(c=>`<option>${safe(c.name)}</option>`).join('')}</select></label><div class="storage-metrics"><div><small>Local target</small><b>SQLite</b><span>ไฟล์ local-warehouse.sqlite3 ในโฟลเดอร์ U-ETL ของ Windows</span></div><div><small>Discovered tables</small><b>${valid.length}</b><span>รายการ metadata ที่ค้นพบ ไม่ใช่จำนวนตารางที่โหลดแล้ว</span></div></div><label class="field">Rows to load per table (default 100)<input id="local-extract-row-limit" type="number" min="1" max="2147483647" value="100"></label><label class="muted">ตั้งจำนวนแถวสูงสุดที่จะอ่านในแต่ละ Table; ค่าเริ่มต้นคือ 100 แก้ไขได้ก่อนเริ่มโหลด</label><label><input id="local-extract-budget-ack" type="checkbox"> I confirm this bounded Source read and that all supported scalar columns (including Primary Key columns) from the returned rows will be stored on this computer.</label></section><div id="local-extract-status" class="callout" role="status">Enter the maximum rows per table, then load explicitly. Repeated runs upsert by Primary Key.</div><div class="tablewrap card"><table class="table"><thead><tr><th>Source connection</th><th>Database</th><th>Schema</th><th>Table</th><th>Primary key</th><th>Rows stored</th><th>Storage</th><th>Last collection</th><th>Actions</th></tr></thead><tbody>${rows||'<tr><td colspan="9" class="empty-cell">ยังไม่มีข้อมูลที่จัดเก็บ · Test/Discover ใน Database Connection ก่อน (การ Discover ไม่ได้คัดลอกแถวข้อมูล)</td></tr>'}</tbody></table></div><div class="actions"><button onclick="S.page='activity';render()">Collection history</button><button class="primary" onclick="go('create')">ใช้ข้อมูลสร้าง Dataset</button></div><p class="callout">The local SQLite file stores real Oracle rows on this computer. Views and tables without a discovered Primary Key are blocked. Production Server DB adapter and scheduling are not included.</p>`;
}
function collectionObjectKey(snapshot){return `${snapshot.sourceId}|${snapshot.schema}|${snapshot.table}`;}
function collectionObjectLabel(snapshot){return `${snapshot.sourceName||P.connections.find(c=>c.id===snapshot.sourceId)?.name||'Source'} · ${snapshot.schema}.${snapshot.table}`;}
function discoveredForeignKeyRelations(snapshots){const bySourceObject=new Map(snapshots.map(s=>[collectionObjectKey(s),s]));const found=[];for(const child of snapshots)for(const fk of child.foreign_keys||[]){const parent=snapshots.find(s=>s.sourceId===child.sourceId&&s.schema===fk[3]&&s.table===fk[4]);if(!parent)continue;const id=`fk|${collectionObjectKey(child)}|${fk[0]}|${fk[2]}`;if(found.some(r=>r.id===id))continue;found.push({id,parentKey:collectionObjectKey(parent),childKey:collectionObjectKey(child),parentColumn:fk[5],childColumn:fk[1],constraint:fk[0],evidence:'Oracle Foreign Key'});}return found;}
function collectionRelationshipFormMarkup(snapshots){const options=snapshots.map(s=>`<option value="${safe(collectionObjectKey(s))}">${safe(collectionObjectLabel(s))}</option>`).join('');return `<form class="collection-relationship-form card" onsubmit="return saveCollectionRelationship(event)"><h4>Add table dependency</h4><p>Parent is loaded before Child. Choose the matching key columns used to relate the records.</p><div class="form"><label class="field">Parent table<select id="collection-parent-table" required onchange="collectionRelationshipFormChanged()"><option value="">Select parent</option>${options}</select></label><label class="field">Parent key column<select id="collection-parent-column" required disabled><option value="">Select parent first</option></select></label><label class="field">Child table<select id="collection-child-table" required onchange="collectionRelationshipFormChanged()"><option value="">Select child</option>${options}</select></label><label class="field">Child foreign/business key<select id="collection-child-column" required disabled><option value="">Select child first</option></select></label></div><button type="submit" ${snapshots.length<2?'disabled':''}>Save relationship</button><small>For manually defined edges, confirm the key mapping with the data owner. This saves configuration only; it does not query or load data.</small></form>`;}
function renderCollectionRelationships(snapshots){const detected=discoveredForeignKeyRelations(snapshots),manual=collectionRelationships.filter(r=>snapshots.some(s=>collectionObjectKey(s)===r.parentKey)&&snapshots.some(s=>collectionObjectKey(s)===r.childKey)),detectedRows=detected.map(r=>`<li><b>${safe(collectionObjectLabel(snapshots.find(s=>collectionObjectKey(s)===r.parentKey)))}</b> <code>${safe(r.parentColumn)}</code> → <b>${safe(collectionObjectLabel(snapshots.find(s=>collectionObjectKey(s)===r.childKey)))}</b> <code>${safe(r.childColumn)}</code><small class="muted">Detected from Source FK ${safe(r.constraint)}</small></li>`).join(''),manualRows=manual.map(r=>`<li><b>${safe(collectionObjectLabel(snapshots.find(s=>collectionObjectKey(s)===r.parentKey)))}</b> <code>${safe(r.parentColumn)}</code> → <b>${safe(collectionObjectLabel(snapshots.find(s=>collectionObjectKey(s)===r.childKey)))}</b> <code>${safe(r.childColumn)}</code><small class="muted">${safe(r.evidence||'User defined')} · Parent loads first</small><button type="button" onclick="removeCollectionRelationship('${safe(encodeURIComponent(r.id))}')">Remove</button></li>`).join('');return `<section class="card collection-relationships"><h3>Table relationships &amp; collection order</h3><p>Use relationships to define key mapping and load dependencies, such as A → B → C and B → E. An edge means the Parent table must be loaded before the Child table.</p>${detected.length?`<h4>Detected from Source foreign keys</h4><ul class="collection-relationship-list">${detectedRows}</ul>`:'<p class="muted">No matching Source foreign keys found among the tables in this list.</p>'}${collectionRelationshipFormMarkup(snapshots)}${manual.length?`<h4>Saved collection dependencies</h4><ul class="collection-relationship-list">${manualRows}</ul>`:''}<p class="callout">Relationship settings are saved locally as configuration only. Target connection, scheduler, incremental extraction and actual loading are not implemented yet.</p></section>`;}
function collectionRelationshipFormChanged(){const snapshots=window.realSourceSnapshotList?.()||[];for(const [side,id] of [['parent','collection-parent-table'],['child','collection-child-table']]){const table=document.getElementById(id),column=document.getElementById(`collection-${side}-column`),selected=column?.value,snapshot=snapshots.find(s=>collectionObjectKey(s)===table?.value),columns=[...new Set((snapshot?.columns||[]).map(c=>c[0]).filter(Boolean))];if(!column)continue;column.innerHTML=`<option value="">Select column</option>${columns.map(name=>`<option value="${safe(name)}" ${name===selected?'selected':''}>${safe(name)}</option>`).join('')}`;column.disabled=!snapshot||!columns.length;}}
function collectionDependencyWouldCycle(parentKey,childKey,snapshots){const edges=[...discoveredForeignKeyRelations(snapshots),...collectionRelationships],next=new Map();for(const edge of edges){if(!next.has(edge.parentKey))next.set(edge.parentKey,[]);next.get(edge.parentKey).push(edge.childKey);}const pending=[childKey],seen=new Set();while(pending.length){const node=pending.pop();if(node===parentKey)return true;if(seen.has(node))continue;seen.add(node);pending.push(...(next.get(node)||[]));}return false;}
function saveCollectionRelationship(event){event.preventDefault();const parentKey=document.getElementById('collection-parent-table')?.value,childKey=document.getElementById('collection-child-table')?.value,parentColumn=document.getElementById('collection-parent-column')?.value,childColumn=document.getElementById('collection-child-column')?.value;if(!parentKey||!childKey||!parentColumn||!childColumn)return notify('Choose both tables and key columns.');if(parentKey===childKey)return notify('Parent and Child must be different tables.');if(collectionRelationships.some(r=>r.parentKey===parentKey&&r.childKey===childKey&&r.parentColumn===parentColumn&&r.childColumn===childColumn))return notify('This relationship is already saved.');const snapshots=window.realSourceSnapshotList?.()||[],parent=snapshots.find(s=>collectionObjectKey(s)===parentKey),child=snapshots.find(s=>collectionObjectKey(s)===childKey);if(!parent||!child||parent.sourceId!==child.sourceId)return notify('Choose tables from the same Source connection.');if(collectionDependencyWouldCycle(parentKey,childKey,snapshots))return notify('This dependency creates a cycle in the collection order.');collectionRelationships.push({id:`manual|${parentKey}|${parentColumn}|${childKey}|${childColumn}`,parentKey,childKey,parentColumn,childColumn,evidence:'User defined · verify with data owner',createdAt:new Date().toISOString()});try{localStorage.setItem(collectionRelationshipStorageKey,JSON.stringify(collectionRelationships));}catch{}render();return false;}
function removeCollectionRelationship(encodedId){const id=decodeURIComponent(encodedId);collectionRelationships=collectionRelationships.filter(r=>r.id!==id);try{localStorage.setItem(collectionRelationshipStorageKey,JSON.stringify(collectionRelationships));}catch{}render();}
const copiesWithoutRelationships=copies;
copies=function(){const snapshots=(window.realSourceSnapshotList?.()||[]).filter(s=>P.connections.some(c=>c.id===s.sourceId&&c.revision===(s.configRevision||1)));return copiesWithoutRelationships()+renderCollectionRelationships(snapshots);};
renderCollectionRelationships=function(snapshots){const byKey=new Map(snapshots.map(s=>[collectionObjectKey(s),s])),options=snapshots.map(s=>`<option value="${safe(collectionObjectKey(s))}">${safe(collectionObjectLabel(s))}</option>`).join(''),draftItems=collectionLoadDraft.items.map((key,index)=>{const table=byKey.get(key);return `<li><span><b>${index+1}.</b> ${safe(table?collectionObjectLabel(table):key)}</span><div class="load-sequence-item-actions"><button type="button" onclick="moveCollectionLoadItem(${index},-1)" ${index===0?'disabled':''} aria-label="Move up">↑</button><button type="button" onclick="moveCollectionLoadItem(${index},1)" ${index===collectionLoadDraft.items.length-1?'disabled':''} aria-label="Move down">↓</button><button type="button" onclick="removeCollectionLoadItem(${index})">Remove</button></div></li>`;}).join(''),groups=collectionLoadGroups.map(group=>`<article class="saved-load-group"><div><b>${safe(group.name)}</b><small>${group.items.length} tables · Sequential · Manual run</small></div><ol>${group.items.map((key,index)=>{const table=byKey.get(key);return `<li>${index+1}. ${safe(table?collectionObjectLabel(table):key)}</li>`;}).join('')}</ol><div class="actions"><button type="button" class="load-group-run" onclick="runLocalCollectionGroup('${encodeURIComponent(group.id)}')">Run group</button><button type="button" onclick="editCollectionLoadGroup('${safe(group.id)}')">Edit order</button><button type="button" onclick="deleteCollectionLoadGroup('${safe(group.id)}')">Delete group</button></div></article>`).join('');return `<section class="card collection-relationships"><h3>Load groups &amp; table order</h3><p>Run a saved group manually. Tables are processed in the displayed order; if one fails, later tables are not started.</p>${collectionLoadGroups.length?`<h4>Saved load groups</h4><div class="saved-load-groups">${groups}</div>`:'<p class="muted">No load groups saved yet.</p>'}<form class="collection-relationship-form card" onsubmit="return saveCollectionLoadGroup(event)"><h4>${collectionLoadDraft.id?'Edit load group':'Create load group'}</h4><label class="field">Load group name<input id="collection-load-group-name" required maxlength="100" placeholder="e.g. Production daily load" value="${safe(collectionLoadDraft.name)}" oninput="collectionLoadDraft.name=this.value"></label><div class="load-sequence-add"><label class="field">Add table to sequence<select id="collection-load-table" ${snapshots.length?'':'disabled'}><option value="">Select a discovered table</option>${options}</select></label><button type="button" onclick="addCollectionLoadItem()" ${snapshots.length?'':'disabled'}>Add table</button></div><h4>Load order</h4>${draftItems?`<ol class="load-sequence-list">${draftItems}</ol>`:'<p class="muted">Add tables in the order to load them.</p>'}<div class="actions"><button type="submit" class="primary" ${collectionLoadDraft.items.length?'':'disabled'}>Save load group</button>${collectionLoadDraft.id?'<button type="button" onclick="resetCollectionLoadDraft()">Cancel edit</button>':''}</div></form><p class="callout">Each table uses the configured per-table row limit (default 100) and writes to local SQLite. Repeated rows are upserted using the discovered Primary Key; no-PK objects and Views are blocked. This setting limits returned rows, not necessarily Oracle physical I/O or query time. A production deployment still requires a shared server target and operational safeguards.</p></section>`;};
function selectedExtractRowLimit(){const rowLimit=Number(document.getElementById('local-extract-row-limit')?.value);if(!Number.isSafeInteger(rowLimit)||rowLimit<1||rowLimit>2147483647){notify('Enter a whole-number row limit between 1 and 2,147,483,647.');return null;}return rowLimit;}
async function runLocalExtractLoad(sourceId,schema,table){if(location.protocol!=='https:')return notify('Open the secure local app at https://localhost:8443/ to load data.');if(!realSourceUI.session)return notify('Sign in to the secure local backend first.');if(!document.getElementById('local-extract-budget-ack')?.checked)return notify('Confirm the bounded Oracle read and local storage first.');const rowLimit=selectedExtractRowLimit();if(rowLimit===null)return;const snapshot=window.realSourceSnapshots?.[`${sourceId}|${schema}|${table}`];if(!snapshot||!snapshot.keys?.some(k=>k[1]==='P'))return notify('This table has no discovered Primary Key; loading is blocked to prevent duplicates.');const pk=snapshot.keys.filter(k=>k[1]==='P').map(k=>k[2]),dataColumns=snapshot.columns.filter(c=>['VARCHAR2','NVARCHAR2','CHAR','NCHAR','NUMBER','FLOAT','BINARY_FLOAT','BINARY_DOUBLE','DATE'].some(t=>String(c[2]).startsWith(t))).map(c=>c[0]),columns=[...new Set([...pk,...dataColumns])];return runLocalExtractLoadRequest(sourceId,schema,table,columns,rowLimit);}
async function runLocalExtractLoadRequest(sourceId,schema,table,columns,rowLimit){const status=document.getElementById('local-extract-status');realSourceUI.busy=true;if(status)status.textContent=`Loading ${schema}.${table}: reading at most ${rowLimit} rows…`;document.querySelectorAll('.load-group-run,.table-load-run').forEach(button=>button.disabled=true);try{const job=await realSourceWaitForProfileJob(sourceId,'extract_load',{schema,table,timeout:30,row_limit:rowLimit,columns,budget_ack:true});const result=job.result||{};if(status)status.textContent=`Loaded ${result.rows_received} source rows into local SQLite for ${schema}.${table}; ${result.rows_written} inserted/updated · ${result.target_rows} rows currently stored. Primary Key: ${result.primary_keys.join(', ')}.`;S.notice=`Load completed for ${schema}.${table}: ${result.rows_received} rows read.`;return result;}catch(error){if(status)status.textContent=`Load failed for ${schema}.${table}: ${error.message}. Later tables were not started.`;S.notice=error.message;return null;}finally{realSourceUI.busy=false;document.querySelectorAll('.load-group-run,.table-load-run').forEach(button=>button.disabled=false);if(S.page==='copies')refreshLocalTargetStatuses();}}
async function runLocalCollectionGroup(encodedId){const group=collectionLoadGroups.find(g=>g.id===decodeURIComponent(encodedId));if(!group)return notify('Load group not found.');if(location.protocol!=='https:'||!realSourceUI.session)return notify('Sign in to the secure local backend at https://localhost:8443/ before loading.');if(!document.getElementById('local-extract-budget-ack')?.checked)return notify('Confirm the bounded Oracle read and local storage first.');const rowLimit=selectedExtractRowLimit();if(rowLimit===null)return;if(realSourceUI.busy)return notify('Another Source operation is already running.');for(const key of group.items){const [sourceId,schema,table]=key.split('|'),snapshot=window.realSourceSnapshots?.[key];if(!snapshot||!snapshot.keys?.some(k=>k[1]==='P'))return notify(`Load group stopped before running: ${schema}.${table} has no discovered Primary Key.`);}realSourceUI.busy=true;let completed=0;const status=document.getElementById('local-extract-status');try{for(const key of group.items){const [sourceId,schema,table]=key.split('|'),snapshot=window.realSourceSnapshots[key],pk=snapshot.keys.filter(k=>k[1]==='P').map(k=>k[2]),dataColumns=snapshot.columns.filter(c=>['VARCHAR2','NVARCHAR2','CHAR','NCHAR','NUMBER','FLOAT','BINARY_FLOAT','BINARY_DOUBLE','DATE','TIMESTAMP'].some(t=>String(c[2]).startsWith(t))).map(c=>c[0]),columns=[...new Set([...pk,...dataColumns])];if(status)status.textContent=`Group ${group.name} · ${completed+1}/${group.items.length} · ${schema}.${table} · up to ${rowLimit} rows`;const job=await realSourceWaitForProfileJob(sourceId,'extract_load',{schema,table,timeout:30,row_limit:rowLimit,columns,budget_ack:true});if(job.state!=='read_completed')throw new Error(`${schema}.${table} did not complete`);completed++;}if(status)status.textContent=`Load group “${group.name}” finished in saved order: ${completed} tables completed. Maximum ${rowLimit} rows per table.`;S.notice=`Load group ${group.name} completed: ${completed} tables.`;}catch(error){if(status)status.textContent=`Load group stopped after ${completed} table(s): ${error.message}. Fix/retry before later tables run.`;S.notice=error.message;}finally{realSourceUI.busy=false;document.querySelectorAll('.load-group-run,.table-load-run').forEach(button=>button.disabled=false);if(S.page==='copies')refreshLocalTargetStatuses();}}
function persistCollectionLoadGroups(){try{localStorage.setItem(collectionLoadGroupsStorageKey,JSON.stringify(collectionLoadGroups));}catch{}}
function addCollectionLoadItem(){const key=document.getElementById('collection-load-table')?.value;if(!key)return notify('Select a discovered table to add to this load group.');if(collectionLoadDraft.items.includes(key))return notify('This table is already in the current load group.');collectionLoadDraft.items.push(key);render();}
function removeCollectionLoadItem(index){collectionLoadDraft.items.splice(index,1);render();}
function moveCollectionLoadItem(index,offset){const target=index+offset;if(target<0||target>=collectionLoadDraft.items.length)return;[collectionLoadDraft.items[index],collectionLoadDraft.items[target]]=[collectionLoadDraft.items[target],collectionLoadDraft.items[index]];render();}
function saveCollectionLoadGroup(event){event.preventDefault();const name=(document.getElementById('collection-load-group-name')?.value||collectionLoadDraft.name).trim();if(!name)return notify('Enter a name for this load group.');if(!collectionLoadDraft.items.length)return notify('Add at least one table to the load order.');const group={id:collectionLoadDraft.id||`load-group-${Date.now()}`,name,items:[...collectionLoadDraft.items]};const index=collectionLoadGroups.findIndex(g=>g.id===group.id);if(index<0)collectionLoadGroups.push(group);else collectionLoadGroups[index]=group;persistCollectionLoadGroups();collectionLoadDraft={id:null,name:'',items:[]};render();return false;}
function editCollectionLoadGroup(id){const group=collectionLoadGroups.find(g=>g.id===id);if(!group)return;collectionLoadDraft={id:group.id,name:group.name,items:[...group.items]};render();}
function deleteCollectionLoadGroup(id){collectionLoadGroups=collectionLoadGroups.filter(g=>g.id!==id);persistCollectionLoadGroups();if(collectionLoadDraft.id===id)collectionLoadDraft={id:null,name:'',items:[]};render();}
function resetCollectionLoadDraft(){collectionLoadDraft={id:null,name:'',items:[]};render();}
let localTargetStatusPending=false;
async function refreshLocalTargetStatuses(){if(localTargetStatusPending||!realSourceUI.session||location.protocol!=='https:'||S.page!=='copies')return;const cells=[...document.querySelectorAll('[data-local-load-rows]')];if(!cells.length)return;localTargetStatusPending=true;try{const result=await realApi('local-target/status'),tables=result.tables||{};for(const cell of cells){const key=cell.dataset.localLoadRows,status=tables[key],viewButton=document.querySelector(`[data-stored-view="${CSS.escape(key)}"]`);if(viewButton)viewButton.disabled=!status||status.target_rows<1;if(!status)continue;const rows=document.querySelector(`[data-local-load-rows="${CSS.escape(key)}"]`),storage=document.querySelector(`[data-local-load-storage="${CSS.escape(key)}"]`),loaded=document.querySelector(`[data-local-load-time="${CSS.escape(key)}"]`);if(rows)rows.textContent=`${status.target_rows} rows`;if(storage)storage.textContent='Local SQLite';if(loaded)loaded.textContent=status.last_load_at?new Date(status.last_load_at).toLocaleString():'—';}}catch{}finally{localTargetStatusPending=false;}}
const resetLegacyRender=render;
render=function(){if(!explicitDemoMode&&['overview','mapping','etl','relationships','explorer','quality','runs','settings'].includes(S.page))S.page='create';resetLegacyRender();if(!explicitDemoMode){document.querySelector('.workflow-nav')?.remove();document.querySelector('.sync-summary')?.remove();document.querySelector('.content .wizard')?.remove();document.querySelector('.content .toolbar:has([aria-label="Page state"])')?.remove();}refreshLocalTargetStatuses();};
const layoutWithTextLogo=layout;
layout=function(){layoutWithTextLogo();const logo=document.querySelector('.masthead-logo');if(logo)logo.innerHTML='<defs><clipPath id="utac-u-emblem"><circle cx="58" cy="60" r="52"/></clipPath></defs><image href="/assets/utac-logo-source.png" x="6" y="8" width="162.4" height="115.1" preserveAspectRatio="none" clip-path="url(#utac-u-emblem)"/><text x="105" y="83" fill="#62509f" font-family="Segoe UI,Arial,sans-serif" font-size="53" font-weight="700" letter-spacing="-2">-ETL Data Bridge</text>';};
if(!explicitDemoMode){window.datasetWizardStep=1;S.page='sources';}else{S.page='overview';}
render();
if(location.protocol==='https:')realSourceRefreshSession().then(()=>render());
